/**
 * What is selected, resolved against the data: the navigation state records
 * the user's choices, which may point at a Workspace or session that has since
 * gone; this picks the nearest thing that exists. Pure, so it is unit-tested.
 */
import type { SessionId, WorkspaceId } from "@polaris/protocol";
import type { Route } from "../../shared/api.ts";
import type { HostModel, SessionEntry } from "../store/hostModel.ts";
import {
  activeSessions,
  type BarHost,
  barWorkspaces,
  LOCAL_HOST,
  needsYou,
  type TopBarMode,
} from "./topBar.ts";

export type SidebarView = "sessions" | "needs-you";

export type Pane = "session" | "new-session";

/** The Settings pages (DESIGN.md, Settings); features/machines fills "hosts". */
export type SettingsSection =
  | "appearance"
  | "sessions"
  | "harnesses"
  | "usage"
  | "hosts"
  | "attachments"
  | "reviewer"
  | "github";

export const SETTINGS_SECTIONS: ReadonlyArray<SettingsSection> = [
  "appearance",
  "sessions",
  "harnesses",
  "usage",
  "hosts",
  "attachments",
  "rev
];

/** The ⌘O dialog (DESIGN.md, Open folder): which Host it opens on; null for the selected one. */
export interface FolderRoute {
  readonly hostKey: string | null;
}

/** Settings, open over the three zones; null when closed. */
export interface SettingsRoute {
  readonly section: SettingsSection;
  /** Hosts and GitHub accounts: start adding one at once. */
  readonly adding: boolean;
}

export interface NavState {
  readonly mode: Route;
  readonly hostKey: string | null;
  readonly workspaceId: WorkspaceId | null;
  readonly sessionId: SessionId | null;
  readonly pane: Pane;
  readonly sidebar: SidebarView;
  readonly jumpOpen: boolean;
  /** The keyboard shortcut overlay (⌘/ or ?). */
  readonly helpOpen: boolean;
  /** The ⌘O dialog, one of the shell's overlays; null when closed. */
  readonly folder: FolderRoute | null;
  readonly settings: SettingsRoute | null;
  readonly topBar: TopBarMode;
  /** Sessions and Workspaces opened lately, newest first (`recentKey`), for the jump menu. */
  readonly recent: ReadonlyArray<string>;
  /** The session last open in each Workspace (`workspaceKey`), restored on switching back. */
  readonly lastSession: Readonly<Record<string, SessionId>>;
  /** Machine-mode Workspace groups the user folded or unfolded (`workspaceKey`). */
  readonly folded: Readonly<Record<string, boolean>>;
}

export const initialNav: NavState = {
  mode: "orchestrate",
  hostKey: null,
  workspaceId: null,
  sessionId: null,
  pane: "session",
  sidebar: "sessions",
  jumpOpen: false,
  helpOpen: false,
  folder: null,
  settings: null,
  topBar: "workspaces",
  recent: [],
  lastSession: {},
  folded: {},
};

export const workspaceKey = (hostKey: string, workspaceId: string) =>
  `${hostKey}\u0000${workspaceId}`;

export type RecentKind = "session" | "workspace";

/** One recent item: its kind, Host and id. */
export const recentKey = (kind: RecentKind, hostKey: string, id: string) =>
  `${kind}\u0000${hostKey}\u0000${id}`;

export const RECENT_LIMIT = 8;

/** `key` moved to the front, without duplicates, capped. */
export const withRecent = (recent: ReadonlyArray<string>, key: string) =>
  [key, ...recent.filter((k) => k !== key)].slice(0, RECENT_LIMIT);

export interface Selection {
  readonly mode: Route;
  readonly topBar: TopBarMode;
  readonly hostKey: string | null;
  readonly workspaceId: WorkspaceId | null;
  readonly sessionId: SessionId | null;
  readonly pane: Pane;
  readonly sidebar: SidebarView;
  readonly settings: SettingsRoute | null;
}

/** Sidebar order: Needs You first (rule/needs-you-is-loudest), then newest first; stable while working. */
export const sessionOrder = (a: SessionEntry, b: SessionEntry) =>
  Number(needsYou(b)) - Number(needsYou(a)) ||
  b.session.createdAt.localeCompare(a.session.createdAt);

export interface ResolveInput {
  readonly nav: NavState;
  readonly bar: ReadonlyArray<BarHost>;
  readonly models: Readonly<Record<string, HostModel>>;
}

const pickHost = ({ nav, bar }: ResolveInput): string | null => {
  const known = bar.find((h) => h.host.key === nav.hostKey);

  if (known !== undefined) return known.host.key;

  // No choice yet: a Host with Workspaces; else this Mac (it runs sessions in its home
  // directory), else any connected Host; bar order puts this Mac last, so ask for it.
  const connected = (h: BarHost) => h.host.status.state === "connected";

  const pick =
    bar.find((h) => h.workspaces.length > 0) ??
    bar.find((h) => h.host.key === LOCAL_HOST && connected(h)) ??
    bar.find(connected) ??
    bar.find((h) => h.host.key === LOCAL_HOST) ??
    bar[0];

  return pick?.host.key ?? null;
};

const pickWorkspace = (input: ResolveInput, hostKey: string | null): WorkspaceId | null => {
  const { nav, bar } = input;
  const host = bar.find((h) => h.host.key === hostKey);
  const shown = host?.workspaces ?? [];

  if (shown.some((w) => w.workspace.id === nav.workspaceId)) return nav.workspaceId;

  return shown[0]?.workspace.id ?? null;
};

const pickSession = (
  input: ResolveInput,
  hostKey: string,
  workspaceId: WorkspaceId | null
): SessionId | null => {
  const { nav, models } = input;
  const model = models[hostKey];

  if (model === undefined) return null;

  const inScope = (id: SessionId | null | undefined) => {
    const entry = id === null || id === undefined ? undefined : model.sessions.get(id);

    return entry !== undefined &&
      entry.session.state !== "archived" &&
      (workspaceId === null || entry.session.workspaceId === workspaceId)
      ? entry.session.id
      : null;
  };

  const chosen = inScope(nav.sessionId);

  if (chosen !== null || workspaceId === null) return chosen;

  const remembered = inScope(nav.lastSession[workspaceKey(hostKey, workspaceId)]);

  if (remembered !== null) return remembered;

  return [...activeSessions(model, workspaceId)].sort(sessionOrder)[0]?.session.id ?? null;
};

/** A chosen session decides its Workspace, even one selected before its SessionCreated arrived. */
const followSession = ({ nav, models }: ResolveInput): NavState => {
  const entry =
    nav.hostKey === null || nav.sessionId === null
      ? undefined
      : models[nav.hostKey]?.sessions.get(nav.sessionId);

  return entry === undefined ? nav : { ...nav, workspaceId: entry.session.workspaceId };
};

export const resolveSelection = (raw: ResolveInput): Selection => {
  const input = { ...raw, nav: followSession(raw) };
  const { nav, bar } = input;

  // In the Workspace bar a stale Workspace falls back to the first chip, on any Host; a
  // Host chosen on its own (its label: add a Workspace, or what needs attention) is kept.
  const hostOnly = nav.workspaceId === null && bar.some((h) => h.host.key === nav.hostKey);

  const stale =
    nav.topBar === "workspaces" &&
    !hostOnly &&
    !barWorkspaces(bar).some(
      (w) => w.hostKey === nav.hostKey && w.workspace.id === nav.workspaceId
    );

  const first = stale ? barWorkspaces(bar)[0] : undefined;
  const hostKey = first?.hostKey ?? pickHost(input);
  const workspaceId = first?.workspace.id ?? pickWorkspace(input, hostKey);

  const sessionId =
    hostKey === null || nav.pane === "new-session"
      ? null
      : pickSession(input, hostKey, workspaceId);

  return {
    mode: nav.mode,
    topBar: nav.topBar,
    hostKey,
    workspaceId,
    sessionId,
    pane: nav.pane,
    sidebar: nav.sidebar,
    settings: nav.settings,
  };
};

/**
 * idle: a Daemon with a few registered Workspaces (git repos) and Dormant
 * Agent Sessions, doing nothing. CPU should be ~0 and wakeups rare: on a
 * laptop or a Raspberry Pi an idle Daemon must cost nothing.
 *
 * The sessions are made Dormant the way it happens in life: they run a Turn,
 * then the Daemon restarts. Measured first with one Client connected and
 * subscribed (a Desktop App in the background), then with no Client.
 */
import { join } from "node:path";
import { Effect, Stream } from "effect";
import { awaitReady, cleanup, connect, createTempDir } from "../daemon.ts";
import { registerWorkspace, settle, startSession, waitUntil, watchSession } from "../drive.ts";
import { smallRepo } from "../fixtures.ts";
import { startSampler } from "../sampler.ts";
import { cpu, type Metric, memory, type Scenario, throughput } from "../types.ts";

const WORKSPACES = 3;

const SESSIONS = 6;

export const idle: Scenario = {
  name: "idle",
  description: "idle Daemon with Workspaces and Dormant sessions: CPU %, wakeups, RSS",
  run: (ctx) =>
    Effect.gen(function* () {
      const windowMs = ctx.quick ? 10_000 : 30_000;

      const root = yield* Effect.acquireRelease(
        Effect.sync(() => createTempDir("idle")),
        (dir) => Effect.sync(() => cleanup(dir))
      );

      const repos = Array.from({ length: WORKSPACES }, (_, i) => smallRepo(join(root, `ws${i}`)));

      // Set up: Workspaces and sessions that each ran one Turn.
      const home = yield* Effect.acquireRelease(
        Effect.sync(() => createTempDir("home")),
        (dir) => Effect.sync(() => cleanup(dir))
      );

      yield* Effect.scoped(
        Effect.gen(function* () {
          const daemon = yield* ctx.launch({ home });
          yield* awaitReady(daemon);
          const client = yield* connect(daemon, "socket", "setup");
          const ids: Array<string> = [];

          for (const [i, repo] of repos.entries()) {
            const workspaceId = yield* registerWorkspace(client, repo, `ws${i}`);

            for (let s = 0; s < SESSIONS / WORKSPACES; s++) {
              const id = `idle-${i}-${s}`;
              ids.push(id);
              yield* startSession(client, {
                sessionId: id,
                workspaceId,
                script: { items: 5, deltasPerItem: 5, deltaIntervalMs: 1 },
              });
            }
          }

          for (const id of ids) {
            const watch = yield* watchSession(client, id);
            yield* waitUntil(() => watch.state === "idle", 60_000, `${id} idle`);
          }
        })
      );

      const con
      // Restart onto the same store: the sessions come back Dormant.
      const daemon = yield* ctx.launch({ home });
      yield* awaitReady(daemon);
      const sampler = yield* ctx.sample(daemon, 500);
      const metrics: Record<string, Metric> = {};

      const notes: Array<string> =
        constellations === 0
          ? []
          : [
              `${constellations} running Constellations with Dormant worker sessions re-folded from the event log; no worker Turns started during measurement`,
            ];

      yield* Effect.scoped(
        Effect.gen(function* () {
          const client = yield* connect(daemon, ctx.transport, "idle-client");
          yield* Stream.runDrain(
            client.connection.client.subscribeHost({ afterSequence: null })
          ).pipe(Effect.forkScoped);
          yield* watchSession(client, "idle-0-0");
          yield* settle(5000);
          const from = sampler.sample().t;
          yield* settle(windowMs);
          const report = sampler.report(from - 1, sampler.sample().t);
          metrics.client_cpu_avg_pct = cpu(report.cpuAvgPct, {
            tolerance: { relative: 1, absolute: 0.5 },
          });
          metrics.client_cpu_max_pct = cpu(report.cpuPct.max, { info: true });
          metrics.client_rss_mib = memory(report.rssBytes.median);

          if (report.footprintBytes)
            metrics.client_footprint_mib = memory(report.footprintBytes.median);

          if (report.wakeupsPerSec !== null) {
            metrics.client_wakeups_per_s = throughput(report.wakeupsPerSec, "/s", {
              kind: "count",
              better: "lower",
              tolerance: { relative: 1, absolute: 5 },
            });
          }
        })
      );

      // A bare Bun process with one far-off timer, sampled over the same window: the floor.
      const bare = yield* Effect.acquireRelease(
        Effect.sync(() => Bun.spawn(["bun", "-e", "setInterval(() => {}, 1 << 30)"])),
        (proc) => Effect.sync(() => proc.kill())
      );

      const floor = yield* Effect.acquireRelease(
        Effect.sync(() => startSampler({ roots: () => [bare.pid], intervalMs: 500 })),
        (s) => Effect.sync(() => s.stop())
      );

      yield* settle(3000);
      const from = sampler.sample().t;
      const floorFrom = floor.sample().t;
      yield* settle(windowMs);
      const report = sampler.report(from - 1, sampler.sample().t);
      const floorReport = floor.report(floorFrom - 1, floor.sample().t);
      metrics.bare_bun_cpu_avg_pct = cpu(floorReport.cpuAvgPct, { info: true });
      metrics.bare_bun_rss_mib = memory(floorReport.rssBytes.median, { info: true });

      if (floorReport.wakeupsPerSec !== null) {
        metrics.bare_bun_wakeups_per_s = throughput(floorReport.wakeupsPerSec, "/s", {
          kind: "count",
          better: "lower",
          info: true,
        });
      }

      metrics.noclient_cpu_avg_pct = cpu(report.cpuAvgPct, {
        tolerance: { relative: 1, absolute: 0.5 },
      });
      metrics.noclient_rss_mib = memory(report.rssBytes.median);

      if (report.footprintBytes)
        metrics.noclient_footprint_mib = memory(report.footprintBytes.median);

      if (report.wakeupsPerSec !== null) {
        metrics.noclient_wakeups_per_s = throughput(report.wakeupsPerSec, "/s", {
          kind: "count",
          better: "lower",
          tolerance: { relative: 1, absolute: 5 },
        });
      }

      metrics.processes = { value: report.maxProcesses, unit: "", kind: "count", better: "lower" };

      // Judge against a bare Bun process sampled over the same window, not against zero:
      // Bun's own event loop and GC timers set the floor.
      const extraCpu = report.cpuAvgPct - floorReport.cpuAvgPct;
      metrics.noclient_cpu_over_bare_pct = cpu(extraCpu, {
        tolerance: { relative: 1, absolute: 0.3 },
      });

      if (extraCpu > 0.3) {
        notes.push(
          `idle CPU without a Client is ${report.cpuAvgPct.toFixed(2)}% of a core, ${extraCpu.toFixed(2)} points above a bare Bun process`
        );
      }

      const extraWakeups =
        report.wakeupsPerSec !== null && floorReport.wakeupsPerSec !== null
          ? report.wakeupsPerSec - floorReport.wakeupsPerSec
          : null;

      if (extraWakeups !== null && extraWakeups > 5) {
        notes.push(
          `${report.wakeupsPerSec!.toFixed(1)} wakeups/s idle with no Client, ${extraWakeups.toFixed(1)}/s above a bare Bun process: timers or polling`
        );
      }

      notes.push(
        `${WORKSPACES} Workspaces, ${SESSIONS} Dormant sessions; ${windowMs / 1000} s windows after a settle; wakeups are ${process.platform === "darwin" ? "idle + interrupt wakeups (proc_pid_rusage)" : "context switches of all threads"}`
      );

      return { metrics, notes };
    }),
};

