    <div data-slot="approval-card" className={cn("flex flex-col", className)} {...props}>
      <div className="flex gap-3 px-3.5 pt-3.5 pb-3">
        <Tile hue={harness} size={32}>
          <PixelHandIcon size={16} className="text-needs-you" />
        </Tile>
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <p className="text-label text-text-strong truncate">{title}</p>
          <p className="text-caption text-text-subtle truncate">{summary}</p>
        </div>
      </div>
      <div className="px-3.5 pb-3">
        <CodeWell>{command}</CodeWell>
      </div>
      <p className="text-caption text-text-subtle truncate px-3.5 pb-3">{where}</p>
      <div className="border-hairline flex items-center gap-1.5 border-t px-3.5 py-2.5">
        <Button variant="primary" onClick={onApprove}>
          Approve
          <Kbd variant="plain">↵</Kbd>
        </Button>
        <Button variant="secondary" className="px-2.5" onClick={onAlwaysAllow}>
          Always here
        </Button>
        <span className="flex-1" />
        <Button variant="ghost" onClick={onDeny}>
          Deny
        </Button>
      </div>
    </div>
  );
}

/** C8: 128 Tasks in nine groups, for the large layout and the frame budget. */
import {
  AttemptId,
  ConstellationNotification,
  ConstellationQuestion,
  NotificationItem,
  TaskId,
} from "@polaris/protocol";
import { startedRecord } from "../model/fold.ts";
import type { ConstellationRecord } from "../model/index.ts";
import { attempt, b1Claim, constellationOf, task } from "./graph.ts";

type Mix = Readonly<{
  done?: number;
  working?: number;
  review?: number;
  waiting?: number;
  ask?: number;
  future?: number;
}>;

const GROUPS: ReadonlyArray<readonly [letter: string, name: string | null, mix: Mix]> = [
  ["A", "A · Events and store", { done: 14 }],
  ["B", "B · Engine decider", { working: 2, done: 16 }],
  ["C", "C · Tool surface", { ask: 1, review: 2, working: 3, waiting: 6 }],
  ["D", "D · Daemon transport", { review: 2, working: 2, done: 12, waiting: 6 }],
  ["E", "E · Desktop tab", { review: 2, working: 2, done: 4, waiting: 12 }],
  ["F", "F · Spec and model tests", { done: 16 }],
  ["H", "G · Bench and leases", { done: 5, waiting: 6 }],
  ["G", null, { done: 4, waiting: 3 }],
  ["X", null, { future: 8 }],
];

const TITLES = [
  "Token revocation on archive",
  "Review and answer tools",
  "Status as a readable outline",
  "Findings with stable codes",
  "Scripted eval on the bench harness",
  "Lead skill instructions",
  "Worker skill instructions",
  "Outbox relay",
  "Bundle transfer",
  "Resume across restarts",
];

const ago = (minutes: number) => new Date(Date.now() - minutes * 60_000).toISOString();

type State = keyof Mix;

const ORDER: ReadonlyArray<State> = ["ask", "review", "working", "done", "waiting", "future"];

const statesOf = (mix: Mix): ReadonlyArray<State> =>
  ORDER.flatMap((key) => Array.from({ length: mix[key] ?? 0 }, () => key));

const attemptFor = (id: string, state: State, n: number) => {
  if (state === "done")
    return attempt({
      taskId: id,
      state: "accepted",
      minutes: 200 - n,
      mergedHead: "abc1234",
      evidence: "verified",
    });

  if (state === "working" || state === "ask")
    return attempt({ taskId: id, state: "working", minutes: 3 + n * 3 });

  return state === "review"
    ? attempt({ taskId: id, state: "review", minutes: 30, claim: b1Claim })
    : null;
};

const askFor = (id: string) =>
  new ConstellationNotification({
    id: `n-${id}`,
    item: NotificationItem.cases.Question.make({
      attemptId: AttemptId.make(`att-${id}-1`),
      question: new ConstellationQuestion({
        id: `q-${id}`,
        to: "user",
        text: "Revoke on archive or on Attempt end?",
        blocking: true,
      }),
    }),
    queuedAt: ago(4),
  });

const titleOf = (letter: string, n: number) =>
  letter === "G"
    ? `${TITLES[n % TITLES.length]} merged`
    : (TITLES[(n + letter.charCodeAt(0)) % TITLES.length] ?? `${letter}${n}`);

export const largeRecord = (): ConstellationRecord => {
  const cells = GROUPS.flatMap(([letter, group, mix]) =>
    statesOf(mix).map((state, index) => ({ letter, group, state, n: index + 1 }))
  );

  const tasks = cells.map(({ letter, group, state, n }) =>
    task({
      id: `${letter}${n}`,
      title: titleOf(letter, n),
      group,
      kind: letter === "G" ? "gate" : "task",
      deps: state === "waiting" || state === "future" ? [`A${(n % 14) + 1}`, "C1"] : [],
      ui: letter === "E" || n % 5 === 0,
    })
  );

  const attempts = cells.flatMap(({ letter, state, n }) => {
    const a = attemptFor(`${letter}${n}`, state, n);

    return a === null ? [] : [a];
  });

  const notifications = cells.flatMap(({ letter, state, n }) =>
    state === "ask" ? [askFor(`${letter}${n}`)] : []
  );

  const base = startedRecord(
    constellationOf({ tasks, attempts, pendingNotifications: notifications }),
    400
  );

  const futures = new Set(tasks.flatMap((t) => (t.id.startsWith("X") ? [t.id] : [])));

  return {
    ...base,
    projections: base.projections.map((p) =>
      futures.has(p.taskId) ? { ...p, state: "future" as const } : p
    ),
    proposals: [
      {
        proposalId: "p-1",
        by: AttemptId.make("att-C3-1"),
        task: {
          id: TaskId.make("X9"),
          title: "Lease bench and smoke",
          kind: "task",
          deps: [],
          area: [],
          brief: "",
          criteria: [],
          suggested: null,
          group: null,
          parent: null,
        },
        at: ago(2),
      },
      {
        proposalId: "p-2",
        by: AttemptId.make("att-D2-1"),
        task: {
          id: TaskId.make("X10"),
          title: "Relay retries with backoff",
          kind: "task",
          deps: [],
          area: [],
          brief: "",
          criteria: [],
          suggested: null,
          group: null,
        },
        at: ago(5),
      },
    ],
  };
};

/**
 * Pure pieces of the machines feature: the Settings rows (`MachineView`) from
 * the settings, the Host list and each Host's install flow, and when a
 * Connection State calls for a background check.
 */
import { type DaemonReport, upgradeDue } from "@polaris/client/install";
import { Predicate } from "effect";
import type { HostView, InstallFlowView, MachineView, SshAliasView } from "../../shared/api.ts";
import { LOCAL_HOST_KEY } from "../hosts.ts";
import type { Settings } from "../settings.ts";
import type { InstallOutcome, InstallSnapshot } from "./installFlow.ts";

/** A Host's install flow as `Machines` tracks it. */
export interface InstallRecord {
  readonly snapshot: InstallSnapshot;
  /** What is happening now (checking or installing), for the progress line. */
  readonly activity: string | null;
  /** The offered build's size, for the approval card. */
  readonly offerSize: number | null;
}

export const installFlowView = ({
  snapshot,
  activity,
  offerSize,
}: InstallRecord): InstallFlowView => ({
  step: snapshot.value,
  activity,
  offer:
    snapshot.context.offer === null ? null : { ...snapshot.context.offer, sizeBytes: offerSize },
  outcome: snapshot.context.outcome,
  problem: snapshot.context.problem,
});

export interface MachineViewsInput {
  readonly settings: Settings;
  readonly hosts: ReadonlyArray<HostView>;
  readonly installs: ReadonlyMap<string, InstallRecord>;
  readonly aliases: ReadonlyArray<SshAliasView>;
}

/** This Mac first (even while switched off), then the remote Hosts in settings order. */
export const machineViews = ({
  settings,
  hosts,
  installs,
  aliases,
}: MachineViewsInput): ReadonlyArray<MachineView> => {
  const status = (key: string) => hosts.find((h) => h.key === key)?.status ?? null;
  const local = hosts.find((h) => h.key === LOCAL_HOST_KEY);
  const localInstall = installs.get(LOCAL_HOST_KEY);

  const localView: MachineView = {
    daemon: null,
    key: LOCAL_HOST_KEY,
    label: local?.label ?? "This Mac",
    colour: null,
    alias: null,
    target: null,
    enabled: settings.local?.enabled ?? true,
    forwardAgent: false,
    remoteCommand: null,
    status: status(LOCAL_HOST_KEY),
    install: localInstall === undefined ? null : installFlowView(localInstall),
  };

  const remotes = (settings.hosts ?? []).map((remote): MachineView => {
    const target = aliases.find((a) => a.alias === remote.alias);
    const install = installs.get(remote.alias);

    return {
      key: remote.alias,
      label: remote.label ?? remote.alias,
      colour: remote.colour ?? null,
      alias: remote.alias,
      target: target === undefined ? null : { hostName: target.hostName, user: target.user },
      enabled: true,
      forwardAgent: remote.forwardAgent ?? false,
      remoteCommand: remote.remoteCommand ?? null,
      status: status(remote.alias),
      install: install === undefined ? null : installFlowView(install),
    };
  });

  return [localView, ...remotes];
};

/** Reasons the install flow can fix: no Daemon installed, or one too old to talk to. */
const INSTALL_REASONS: ReadonlySet<string> = new Set([
  "polaris-not-installed",
  "protocol-mismatch",
]);

/**
 * Whether this status calls for a background check, as a key that changes
 * once per occasion (so a Needs Attention retry every 2 min doesn't probe
 * again): entering Needs Attention for a reason the install flow fixes, or a
 * new connection to a Daemon the bundled build should replace (`upgradeDue`). Null otherwise.
 */
export const backgroundCheckKey = (
  view: HostView,
  bundledVersion: string | null
): string | null => {
  const { status } = view;

  if (view.alias === null) return null;

  if (status.state === "needs-attention" && status.failure !== null) {
    return INSTALL_REASONS.has(status.failure.reason)
      ? `${status.failure.reason}:${status.since}`
      : null;
  }

  if (status.state === "connected" && status.host !== null && bundledVersion !== null) {
    return upgradeDue(status.host.daemonVersion, bundledVersion) ? `upgrade:${status.epoch}` : null;
  }

  return null;
};

/**
 * The local Host's background check: only an upgrade (`upgradeDue`) of the
 * Daemon installed in `home`, once per connection. Null when the app runs its own.
 */
export const localUpgradeKey = (
  view: HostView,
  bundledVersion: string | null,
  home: string | null
): string | null => {
  const { status } = view;

  if (home === null || bundledVersion === null) return null;

  if (status.state !== "connected" || status.host === null) return null;

  return upgradeDue(status.host.daemonVersion, bundledVersion) ? `upgrade:${status.epoch}` : null;
};

const LINGER_COMMAND = /sudo loginctl enable-linger \S+/;

/** What `polaris install|upgrade --json` reported, as the outcome's notes. */
export const reportOutcome = (
  report: DaemonReport,
  base: Pick<InstallOutcome, "kind" | "version" | "from">
): InstallOutcome => {
  const notes = Array.isArray(report.notes) ? report.notes.filter(Predicate.isString) : [];
  const linger = notes.map((note) => LINGER_COMMAND.exec(note)?.[0]).find(Predicate.isString);

  return {
    ...base,
    notes,
    adminCommand: report.linger === "needs-admin" ? (linger ?? null) : null,
  };
};

/**
 * How one Task reads at a glance (DESIGN.md, rule/constellation-colour): its rail glyph, the
 * colour of its id and state word, and whether it needs you.
 */
import type { TaskState } from "@polaris/protocol";
import { Predicate } from "effect";
import { idRanges, span } from "./copy.ts";
import type { Facts, WorkerFacts } from "./facts.ts";
import { currentSetup, type SetupRun } from "./setup.ts";
import type { AttemptData, ConstellationData, ProjectionData, TaskData } from "./types.ts";

export type TaskGlyphKind =
  | "working"
  | "review"
  | "review-unfetched"
  | "needs-you"
  | "accepted"
  | "waiting"
  | "future"
  | "gate"
  | "gate-accepted"
  | "failed"
  | "stopped";

export type Tone = "neutral" | "accepted" | "needs-you" | "failed" | "faint";

/** Why a Task needs you, in the order Needs you ranks them (spec §5). */
export type Attention =
  | { readonly kind: "approval"; readonly since: string }
  | { readonly kind: "question"; readonly text: string }
  | { readonly kind: "handed" }
  | { readonly kind: "stopped" }
  /** Worktree setup failed before the Attempt could start (it ranks with "stopped"). */
  | { readonly kind: "setup"; readonly run: SetupRun };

/** The buckets groups count and filters use. */
export type Bucket = "needs-you" | "review" | "working" | "done" | "waiting" | "future" | "ended";

export interface TaskLook {
  readonly glyph: TaskGlyphKind;
  readonly idTone: Tone;
  readonly word: string;
  readonly wordTone: Tone;
  /** "verified", "reported" or "asserted" after "done". */
  readonly evidence: string | null;
  readonly attention: Attention | null;
  readonly bucket: Bucket;
}

const ENDED: ReadonlySet<TaskState> = new Set(["canceled", "lost", "settled_unverified"]);

/** The rail glyph for a projection; shared with the sidebar's worker rows. */
export const glyphFor = (
  projection: Pick<ProjectionData, "state" | "branchFetched">,
  options: { readonly needsYou: boolean; readonly isGate: boolean }
): TaskGlyphKind => {
  const { state } = projection;

  if (options.needsYou) return "needs-you";

  if (options.isGate && state === "done") return "gate-accepted";

  if (options.isGate && state !== "working" && state !== "review") return "gate";

  if (state === "done") return "accepted";

  if (state === "working") return "working";

  if (state === "review") return projection.branchFetched ? "review" : "review-unfetched";

  if (state === "failed") return "failed";

  if (ENDED.has(state)) return "stopped";

  return state === "future" ? "future" : "waiting";
};

/** The question to the user a Task's latest Attempt is waiting on, if any. */
export const userQuestion = (c: ConstellationData, attemptId: string | null) => {
  if (attemptId === null) return null;

  for (const n of c.pendingNotifications ?? []) {
    if (
      Predicate.isTagged(n.item, "Question") &&
      n.item.attemptId === attemptId &&
      n.item.question.to === "user"
    )
      return n.item.question.text;
  }

  return null;
};

const attentionOf = (
  c: ConstellationData,
  projection: ProjectionData,
  attempt: AttemptData | null,
  worker: WorkerFacts
): Attention | null => {
  if (attempt === null || (projection.state !== "working" && projection.state !== "review"))
    return null;

  if (worker.approvalSince !== null) return { kind: "approval", since: worker.approvalSince };
  const question = userQuestion(c, attempt.id);

  if (question !== null) return { kind: "question", text: question };

  if (projection.state === "review" && attempt.handedUpAt != null) return { kind: "handed" };

  return worker.stoppedWithoutClaiming && projection.state === "working"
    ? { kind: "stopped" }
    : null;
};

const ATTENTION_WORD: Readonly<Record<Attention["kind"], string>> = {
  approval: "needs you",
  question: "asks you",
  handed: "handed to you",
  stopped: "needs you",
  setup: "setup failed",
};

const STATE_WORD: Readonly<Record<TaskState, string>> = {
  future: "future",
  waiting: "waiting",
  ready: "ready",
  working: "working",
  blocked: "blocked",
  review: "in review",
  done: "done",
  canceled: "canceled",
  lost: "lost",
  settled_unverified: "unverified",
  failed: "failed",
};

const BUCKET: Readonly<Record<TaskState, Bucket>> = {
  future: "future",
  waiting: "waiting",
  ready: "waiting",
  working: "working",
  review: "review",
  done: "done",
  canceled: "ended",
  lost: "ended",
  settled_unverified: "ended",
  failed: "ended",
};

const wordFor = (task: TaskData, p: ProjectionData, attempt: AttemptData | null, now: number) => {
  if (p.state === "working" && attempt !== null) return `working · ${span(attempt.startedAt, now)}`;

  if (task.kind === "gate" && (p.state === "waiting" || p.state === "ready"))
    return p.blockedBy.length > 0 ? `waits ${idRanges(p.blockedBy)}` : "ready";

  return STATE_WORD[p.state];
};

const toneOf = (state: TaskState): Tone => {
  if (state === "done") return "accepted";

  if (state === "failed") return "failed";

  return state === "future" || ENDED.has(state) ? "faint" : "neutral";
};

/** Setup runs on the Host outside the worker cap: neutral while running, needs you once failed. */
const setupLook = (run: SetupRun, failed: boolean): TaskLook =>
  failed
    ? {
        glyph: "needs-you",
        idTone: "needs-you",
        word: ATTENTION_WORD.setup,
        wordTone: "needs-you",
        evidence: null,
        attention: { kind: "setup", run },
        bucket: "needs-you",
      }
    : {
        glyph: "waiting",
        idTone: "neutral",
        word: "setting up",
        wordTone: "neutral",
        evidence: null,
        attention: null,
        bucket: "working",
      };

export const taskLook = (
  c: ConstellationData,
  task: TaskData,
  projection: ProjectionData,
  attempt: AttemptData | null,
  facts: Facts
): TaskLook => {
  const setup = currentSetup(facts.setup(task.id), attempt);

  if (setup !== null) return setupLook(setup.run, setup.failed);
  const worker = attempt === null ? null : facts.worker(attempt);
  const attention = worker === null ? null : attentionOf(c, projection, attempt, worker);
  const isGate = task.kind === "gate";
  const glyph = glyphFor(projection, { needsYou: attention !== null, isGate });

  if (attention !== null)
    return {
      glyph,
      idTone: "needs-you",
      word: ATTENTION_WORD[attention.kind],
      wordTone: "needs-you",
      evidence: null,
      attention,
      bucket: "needs-you",
    };
  const slot = worker?.activity?.kind === "slot" ? worker.activity : null;

  if (slot !== null && projection.state === "working")
    return {
      glyph: "waiting",
      idTone: "neutral",
      word: `waiting · ${span(slot.since, facts.now)}`,
      wordTone: "neutral",
      evidence: null,
      attention: null,
      bucket: "working",
    };
  const tone = toneOf(projection.state);

  return {
    glyph,
    idTone: tone === "faint" ? "faint" : tone,
    word: wordFor(task, projection, attempt, facts.now),
    wordTone: tone,
    evidence: projection.state === "done" ? (attempt?.evidence ?? null) : null,
    attention: null,
    bucket: BUCKET[projection.state],
  };
};

