/**
 * Search indexes, one per root (a Workspace or a Worktree), built lazily on
 * the first search or watch and dropped after `idleMs` without use and with
 * no active watcher (default 10 minutes). Each index is fff when its native
 * library loads, else the fallback backend.
 */
import { realpath, stat } from "node:fs/promises"
import { FileError } from "@polaris/protocol"
import { Context, Effect, Layer, Queue, Stream } from "effect"
import { resolveHostPath, toFsFailure } from "./fs.ts"
import { makeFallbackBackend } from "./search/fallback.ts"
import { makeFffBackend } from "./search/fff.ts"
import type { FileChange, GrepHit, GrepQuery, PathHit, SearchBackend } from "./search/types.ts"

export interface FileSearchOptions {
  /** Drop an index after this long without a search and with no watcher. */
  readonly idleMs: number
  /** How often idle indexes are looked for (only while there are any: an idle Daemon sleeps). */
  readonly sweepMs: number
  /** Set false to force the fallback backend (tests; `POLARIS_FFF=off` does the same). */
  readonly useFff: boolean
}

export const defaultFileSearchOptions: FileSearchOptions = {
  idleMs: 10 * 60_000,
  sweepMs: 60_000,
  useFff: true,
}

export class FileSearch extends Context.Service<
  FileSearch,
  {
    readonly searchPaths: (
      root: string,
      query: string,
      limit: number,
    ) => Effect.Effect<ReadonlyArray<PathHit>, FileError>
    readonly grep: (
      root: string,
      query: GrepQuery,
    ) => Effect.Effect<ReadonlyArray<GrepHit>, FileError>
    readonly watch: (root: string) => Stream.Stream<ReadonlyArray<FileChange>, FileError>
    /** Which backend serves `root` right now, if it has an index (diagnostics and tests). */
    readonly backendOf: (root: string) => Effect.Effect<SearchBackend["kind"] | null>
  }
>()("polaris/daemon/files/FileSearch") {}

interface Index {
  readonly backend: Promise<SearchBackend>
  lastUsed: number
  watchers: number
}

const fileError = (path: string, cause: unknown) => {
  const failure = toFsFailure(path, cause)
  return new FileError({ path: failure.path, code: failure.code, message: failure.message })
}

const canonicalRoot = async (input: string): Promise<string> => {
  const path = resolveHostPath(input)
  const real = await realpath(path)
  const stats = await stat(real)
  if (!stats.isDirectory()) {
    throw Object.assign(new Error(`not a directory: ${path}`), { code: "ENOTDIR" })
  }
  return real
}

export const makeFileSearch = (options: FileSearchOptions) =>
  Effect.gen(function* () {
    const indexes = new Map<string, Index>()
    let timer: ReturnType<typeof setInterval> | undefined

    const open = (root: string): Index => {
      const existing = indexes.get(root)
      if (existing !== undefined) {
        existing.lastUsed = Date.now()
        return existing
      }
      const backend = (options.useFff ? makeFffBackend(root) : Promise.resolve(null)).then(
        (fff) => fff ?? makeFallbackBackend(root),
      )
      const index: Index = { backend, lastUsed: Date.now(), watchers: 0 }
      indexes.set(root, index)
      timer ??= setInterval(sweep, options.sweepMs)
      return index
    }

    const drop = (root: string, index: Index) => {
      indexes.delete(root)
      void index.backend.then((backend) => backend.dispose())
    }

    const sweep = () => {
      const now = Date.now()
      for (const [root, index] of indexes) {
        if (index.watchers === 0 && now - index.lastUsed > options.idleMs) drop(root, index)
      }
      if (indexes.size === 0) {
        clearInterval(timer)
        timer = undefined
      }
    }
    const timer = setInterval(sweep, options.sweepMs)
    yield* Effect.addFinalizer(() =>
      Effect.sync(() => {
        clearInterval(timer)
        for (const [root, index] of indexes) drop(root, index)
      }),
    )

    const withBackend = <A>(input: string, f: (backend: SearchBackend) => Promise<A>) =>
      Effect.tryPromise({
        try: async () => {
          const root = await canonicalRoot(input)
          return f(await open(root).backend)
        },
        catch: (cause) => fileError(resolveHostPath(input), cause),
      })

    return FileSearch.of({
      searchPaths: (root, query, limit) =>
        withBackend(root, (backend) => backend.searchPaths(query, Math.max(0, limit))),
      grep: (root, query) =>
        withBackend(root, (backend) => backend.grep({ ...query, limit: Math.max(0, query.limit) })),
      watch: (input) =>
        Stream.callback<ReadonlyArray<FileChange>, FileError>((queue) =>
          Effect.gen(function* () {
            const root = yield* Effect.tryPromise({
              try: () => canonicalRoot(input),
              catch: (cause) => fileError(resolveHostPath(input), cause),
            })
            const index = open(root)
            index.watchers++
            yield* Effect.addFinalizer(() =>
              Effect.sync(() => {
                index.watchers--
                index.lastUsed = Date.now()
              }),
            )
            const backend = yield* Effect.tryPromise({
              try: () => index.backend,
              catch: (cause) => fileError(root, cause),
            })
            // acquireRelease: an interrupt while the watcher is arming still unsubscribes.
            yield* Effect.acquireRelease(
              Effect.tryPromise({
                try: () => backend.watch((batch) => Queue.offerUnsafe(queue, batch)),
                catch: (cause) => fileError(root, cause),
              }),
              (stop) => Effect.sync(stop),
            )
          }),
        ),
      backendOf: (input) =>
        Effect.promise(async () => {
          const root = await canonicalRoot(input).catch(() => null)
          const index = root === null ? undefined : indexes.get(root)
          return index === undefined ? null : (await index.backend).kind
        }),
    })
  })

export const FileSearchLive = (options: Partial<FileSearchOptions> = {}) =>
  Layer.effect(FileSearch, makeFileSearch({ ...defaultFileSearchOptions, ...options }))

/**
 * Per-process memory and CPU counters, read without spawning anything:
 *
 * - **macOS**: `proc_pid_rusage(RUSAGE_INFO_V2)` from libSystem via bun:ffi gives
 *   resident size, `phys_footprint` (what Activity Monitor calls Memory: the pages
 *   the process is charged for, including compressed and swapped), user + system
 *   CPU time (in mach time units, converted with `mach_timebase_info`), idle and
 *   interrupt wakeups, and the CPU time of reaped children. `proc_listchildpids`
 *   walks the tree, `proc_name` names each process.
 * - **Linux**: `/proc/<pid>/stat` (utime, stime, cutime, cstime in clock ticks,
 *   assumed 100 Hz, which is `USER_HZ` on every mainstream kernel), `/proc/<pid>/status`
 *   (VmRSS; footprint = RssAnon + RssShmem, the pages not backed by a file) and the
 *   voluntary + involuntary context switches of every thread as the wakeup count.
 *   Children come from `/proc/<pid>/task/<tid>/children`.
 * - Anything else, or when the above fails: `ps -o pid=,ppid=,rss=,time=,comm=`
 *   (RSS and CPU only, and it spawns a process per read; CPU time has 10 ms
 *   resolution on macOS but whole seconds with Linux procps).
 *
 * Only processes of the same user can be read, which is all a benchmark needs.
 */
import { readdirSync, readFileSync } from "node:fs";
import { dlopen, FFIType, ptr } from "bun:ffi";

export interface ProcCounters {
  readonly pid: number;
  readonly name: string;
  readonly rssBytes: number;
  /** macOS phys_footprint; Linux RssAnon + RssShmem; null when unknown. */
  readonly footprintBytes: number | null;
  /** User + system CPU time of this process, ns. */
  readonly cpuNs: number;
  /** User + system CPU time of its children that exited and were reaped, ns. */
  readonly childCpuNs: number;
  /** macOS: idle + interrupt wakeups; Linux: context switches of all threads; null when unknown. */
  readonly wakeups: number | null;
}

export interface ProcReader {
  readonly backend: "darwin-libproc" | "linux-procfs" | "ps";
  readonly read: (pid: number) => ProcCounters | null;
  readonly children: (pid: number) => ReadonlyArray<number>;
}

// ── macOS ───────────────────────────────────────────────────────────────────

const RUSAGE_INFO_V2 = 2;

const RUSAGE_V2_SIZE = 160;

const darwinReader = (): ProcReader | null => {
  try {
    const { dlopen, FFIType, ptr } = require("bun:ffi") as typeof import("bun:ffi");

    const lib = dlopen("/usr/lib/libSystem.B.dylib", {
      proc_pid_rusage: { args: [FFIType.i32, FFIType.i32, FFIType.ptr], returns: FFIType.i32 },
      proc_listchildpids: { args: [FFIType.i32, FFIType.ptr, FFIType.i32], returns: FFIType.i32 },
      proc_name: { args: [FFIType.i32, FFIType.ptr, FFIType.u32], returns: FFIType.i32 },
      mach_timebase_info: { args: [FFIType.ptr], returns: FFIType.i32 },
    });

    const timebase = new Uint32Array(2);
    lib.symbols.mach_timebase_info(ptr(timebase));
    const toNs = (timebase[0] ?? 1) / (timebase[1] ?? 1);
    const usage = new BigUint64Array(RUSAGE_V2_SIZE / 8);
    const nameBuf = new Uint8Array(256);
    const pidBuf = new Int32Array(4096);
    // ptr() is taken per call: JSC may move a small typed array's storage.
    const n = (i: number) => Number(usage[i] ?? 0n);

    return {
      backend: "darwin-libproc",
      read: (pid) => {
        if (lib.symbols.proc_pid_rusage(pid, RUSAGE_INFO_V2, ptr(usage)) !== 0) return null;
        nameBuf.fill(0);
        const len = Math.max(0, lib.symbols.proc_name(pid, ptr(nameBuf), nameBuf.byteLength));
        const nul = nameBuf.indexOf(0);

        // Offsets (u64 words) in struct rusage_info_v2, after the 16-byte uuid.
        return {
          pid,
          name: new TextDecoder().decode(nameBuf.subarray(0, nul >= 0 ? Math.min(nul, len) : len)),
          cpuNs: (n(2) + n(3)) * toNs,
          wakeups: n(4) + n(5),
          rssBytes: n(8),
          footprintBytes: n(9),
          childCpuNs: (n(12) + n(13)) * toNs,
        };
      },
      children: (pid) => {
        const count = lib.symbols.proc_listchildpids(pid, ptr(pidBuf), pidBuf.byteLength);

        return count > 0 ? [...pidBuf.subarray(0, count)] : [];
      },
    };
  } catch {
    return null;
  }
};

// ── Linux ───────────────────────────────────────────────────────────────────

const TICK_NS = 1e9 / 100;

const linuxReader = (): ProcReader | null => {
  try {
    readFileSync("/proc/self/stat", "utf8");
  } catch {
    return null;
  }

  const statusKb = (status: string, key: string): number | null => {
    const match = new RegExp(`^${key}:\\s+(\\d+) kB`, "m").exec(status);

    return match ? Number(match[1]) * 1024 : null;
  };

  return {
    backend: "linux-procfs",
    read: (pid) => {
      try {
        const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
        const close = stat.lastIndexOf(")");
        const name = stat.slice(stat.indexOf("(") + 1, close);

        // Fields after "(comm)": state is field 3, utime 14, stime 15, cutime 16, cstime 17.
        const f = stat
          .slice(close + 2)
          .split(" ")
          .map((x) => Number(x));

        const at = (field: number) => f[field - 3] ?? 0;
        const status = readFileSync(`/proc/${pid}/status`, "utf8");
        const anon = statusKb(status, "RssAnon");
        const shmem = statusKb(status, "RssShmem");
        let wakeups = 0;

        for (const tid of readdirSync(`/proc/${pid}/task`)) {
          try {
            const t = readFileSync(`/proc/${pid}/task/${tid}/status`, "utf8");
            wakeups +=
              Number(/^voluntary_ctxt_switches:\s+(\d+)/m.exec(t)?.[1] ?? 0) +
              Number(/^nonvoluntary_ctxt_switches:\s+(\d+)/m.exec(t)?.[1] ?? 0);
          } catch {}
        }

        return {
          pid,
          name,
          rssBytes: statusKb(status, "VmRSS") ?? 0,
          footprintBytes: anon === null ? null : anon + (shmem ?? 0),
          cpuNs: (at(14) + at(15)) * TICK_NS,
          childCpuNs: (at(16) + at(17)) * TICK_NS,
          wakeups,
        };
      } catch {
        return null;
      }
    },
    children: (pid) => {
      const out: Array<number> = [];

      try {
        for (const tid of readdirSync(`/proc/${pid}/task`)) {
          try {
            const text = readFileSync(`/proc/${pid}/task/${tid}/children`, "utf8").trim();

            if (text) for (const c of text.split(/\s+/)) out.push(Number(c));
          } catch {}
        }
      } catch {}

      return out;
    },
  };
};

// ── ps fallback ─────────────────────────────────────────────────────────────

const psTime = (text: string): number => {
  // [[dd-]hh:]mm:ss[.cc]
  const [days, rest] = text.includes("-") ? text.split("-") : ["0", text];
  const parts = (rest ?? "0").split(":").map(Number);
  let seconds = 0;

  for (const p of parts) seconds = seconds * 60 + p;

  return (Number(days) * 86400 + seconds) * 1e9;
};

const psReader = (): ProcReader => {
  const table = () => {
    const out = Bun.spawnSync(["ps", "-A", "-o", "pid=,ppid=,rss=,time=,comm="]).stdout.toString();

    return out
      .split("\n")
      .map((line) => line.trim().split(/\s+/))
      .filter((cols) => cols.length >= 5)
      .map(([pid, ppid, rss, time, ...comm]) => ({
        pid: Number(pid),
        ppid: Number(ppid),
        rss: Number(rss) * 1024,
        cpuNs: psTime(time ?? "0"),
        name: comm.join(" "),
      }));
  };

  return {
    backend: "ps",
    read: (pid) => {
      const row = table().find((r) => r.pid === pid);

      return row
        ? {
            pid,
            name: row.name,
            rssBytes: row.rss,
            footprintBytes: null,
            cpuNs: row.cpuNs,
            childCpuNs: 0,
            wakeups: null,
          }
        : null;
    },
    children: (pid) =>
      table()
        .filter((r) => r.ppid === pid)
        .map((r) => r.pid),
  };
};

let cached: ProcReader | undefined;

/** The best reader for this platform; `POLARIS_BENCH_PS=1` forces the ps fallback. */
export const procReader = (): ProcReader => {
  if (cached !== undefined) return cached;

  if (process.env.POLARIS_BENCH_PS === "1") cached = psReader();
  else if (process.platform === "darwin") cached = darwinReader() ?? psReader();
  else if (process.platform === "linux") cached = linuxReader() ?? psReader();
  else cached = psReader();

  return cached;
};

/** `root` and every live descendant. */
export const processTree = (root: number, reader = procReader()): Array<number> => {
  const out: Array<number> = [];
  const queue = [root];

  while (queue.length > 0) {
    const pid = queue.shift()!;

    if (out.includes(pid)) continue;
    out.push(pid);
    queue.push(...reader.children(pid));
  }

  return out;
};

/**
 * The handover summary (C9): the previous Lead's prose (the /handoff shape) in a card, then
 * the structured part from the event log as it stood at the switch.
 */
import { Match, Predicate } from "effect";
import type { TaskState } from "@polaris/protocol";
import { PixelHandIcon } from "@polaris/ui";
import { useShellActions } from "../../../shell/hooks.ts";
import {
  clock,
  type ConstellationRecord,
  type Facts,
  glyphFor,
  type Handover,
  LANE_MAX,
  laneWidth,
  type OperatorMessage,
  pluralize,
  type Segment,
  type StripTone,
  type TaskData,
} from "../model/index.ts";
import { ConstellationMark, TaskGlyph } from "./glyphs.tsx";
import { IdLane, laneStyle } from "./lane.tsx";
import { ProgressStrip } from "./strip.tsx";

const SECTION = "text-caption text-text-subtle pt-4 pb-1.5";

const targetOf = (m: OperatorMessage, record: ConstellationRecord) =>
  Match.value(m.target).pipe(
    Match.tagsExhaustive({
      Lead: () => "lead",
      All: () => "all",
      Worker: ({ attemptId }) =>
        record.constellation.attempts.find((a) => a.id === attemptId)?.taskId ?? "worker",
    })
  );

const counts = (h: Handover) => {
  const done = h.projections.filter((p) => p.state === "done").length;
  const review = h.projections.filter((p) => p.state === "review").length;
  const working = h.projections.filter((p) => p.state === "working").length;
  const more = h.projections.length - done - review - working;

  return { done, review, working, more };
};

const TONE: Partial<Record<TaskState, StripTone>> = {
  done: "accepted",
  working: "working",
  review: "review",
  failed: "failed",
};

const stripOf = (h: Handover, tasks: ReadonlyMap<string, TaskData>): ReadonlyArray<Segment> =>
  h.projections.map((p) => ({
    key: p.taskId,
    title: tasks.get(p.taskId)?.title ?? "",
    word: p.state.replaceAll("_", " "),
    tone: TONE[p.state] ?? "waiting",
    harness: tasks.get(p.taskId)?.suggested?.harness ?? null,
  }));

export const HandoverBody = ({
  leadHostKey,
  record,
  handover,
}: {
  readonly leadHostKey: string;
  readonly record: ConstellationRecord;
  readonly handover: Handover;
  readonly facts: Facts;
}) => {
  const { selectSession } = useShellActions();
  const tasks = new Map(record.constellation.tasks.map((t) => [t.id, t]));
  const n = counts(handover);

  const inFlight = handover.inFlight.flatMap((id) => {
    const projection = handover.projections.find((p) => p.latestAttemptId === id);

    return projection === undefined
      ? []
      : [{ id, taskId: projection.taskId, state: projection.state }];
  });

  return (
    <div
      className="min-h-0 flex-1 overflow-y-auto px-5 py-5 select-text"
      data-testid="handover-summary"
    >
      <div className="rounded-row border-hairline bg-surface-raised border px-3.5 py-3">
        <p className="flex items-center gap-2 pb-2">
          <ConstellationMark size={14} />
          <span className="text-label text-text-strong">From the previous lead</span>
          <span className="text-caption text-text-subtle">· /handoff</span>
        </p>
        <p className="text-body text-text-default whitespace-pre-wrap">
          {handover.summary === ""
            ? "The previous lead left no summary. What it handed over is below."
            : handover.summary}
        </p>
      </div>
      <p className="text-body flex flex-wrap items-center gap-2 pt-4">
        <span className="text-text-subtle">At {clock(handover.at)}</span>
        <ProgressStrip segments={stripOf(handover, tasks)} />
        <span className="text-accepted-text">{n.done} done</span>
        <span className="text-text-subtle">
          {n.review} review · {n.working} working · {n.more} more
        </span>
      </p>
      {inFlight.length === 0 ? null : (
        <>
          <h3 className={SECTION}>In flight</h3>
          <ul
            style={laneStyle(
              laneWidth(
                inFlight.map((a) => a.taskId),
                LANE_MAX.tab
              )
            )}
          >
            {inFlight.map((a) => {
              const task = tasks.get(a.taskId);

              return (
                <li key={a.id} className="text-body flex h-8 items-center gap-3">
                  <TaskGlyph
                    glyph={glyphFor(
                      { state: a.state === "review" ? "review" : "working", branchFetched: true },
                      { needsYou: false, isGate: false }
                    )}
                    harness={task?.suggested?.harness ?? null}
                  />
                  <IdLane id={a.taskId} max={LANE_MAX.tab} className="text-text-subtle" />
                  <span className="text-text-default min-w-0 flex-1 truncate">{task?.title}</span>
                  <span className="text-text-subtle">
                    {a.state === "review" ? "claim in review" : "working"}
                  </span>
                </li>
              );
            })}
          </ul>
        </>
      )}
      {handover.questions.length === 0 ? null : (
        <>
          <h3 className={SECTION}>Open questions</h3>
          {handover.questions.map((q) =>
            Predicate.isTagged(q.item, "Question") ? (
              <p key={q.id} className="text-body text-needs-you-text flex items-center gap-2 py-1">
                <PixelHandIcon size={12} className="text-needs-you shrink-0" />
                {q.item.question.text}
              </p>
            ) : null
          )}
        </>
      )}
      {handover.undelivered.length === 0 ? null : (
        <>
          <h3 className={SECTION}>Not yet delivered</h3>
          {handover.undelivered.map((m) => (
            <p key={m.id} className="text-body text-text-default py-1">
              <span className="text-text-subtle">→ {targetOf(m, record)}</span> “{m.text}” · sent
              with the new lead's first turn
            </p>
          ))}
        </>
      )}
      <p className="text-body flex items-center gap-3 pt-5">
        <button
          type="button"
          className="text-text-strong cursor-default"
          onClick={() => selectSession({ hostKey: leadHostKey, sessionId: handover.from })}
        >
          Open the previous lead ↗
        </button>
        <span className="text-text-subtle">
          archived · read-only · {pluralize(record.handovers.length, "handover")}
        </span>
      </p>
    </div>
  );
};

/**
 * Hands each open request (`routes/editor.ts`) to the editor: a file opens in its tab at the
 * line (the editor queues it until it starts), a folder shows in the explorer. Mounted once.
 */
import { useEffect } from "react";
import { type EditorOpenRequest, editorRoute } from "../../routes/editor.ts";
import { type OpenFileRequest, openFile } from "../editor/api.ts";

export interface Delivered {
  readonly request: EditorOpenRequest | null;
  readonly error: string | null;
}

declare global {
  interface Window {
    /** For the smoke test: the last open request and what delivering it threw, if anything. */
    __polarisOpenRequests?: { readonly last: () => Delivered };
  }
}

let last: Delivered = { request: null, error: null };

/** The line and column to reveal; a column only with a line. */
const positionOf = (request: EditorOpenRequest): Pick<OpenFileRequest, "line" | "column"> => {
  if (request.line === null) return {};

  return request.column === null
    ? { line: request.line }
    : { line: request.line, column: request.column };
};

/** A file opens in its tab (queued by the editor until it starts); a folder shows in the explorer. */
const deliver = async (request: EditorOpenRequest) => {
  const { hostKey, workspaceId, path } = request;

  if (request.folder) {
    const { revealInExplorer } = await import("../editor/explorer/index.ts");

    revealInExplorer({ hostKey, workspaceId, path });

    return;
  }

  const { openFile } = await import("../editor/index.ts");

  openFile({ hostKey, workspaceId, path, ...positionOf(request) });
};

export const EditorRequests = () => {
  useEffect(() => {
    window.__polarisOpenRequests = { last: () => last };

    return editorRoute.subscribe(({ request }, previous) => {
      if (request === null || request.seq === previous.request?.seq) return;
      last = { request, error: null };
      deliver(request).catch((cause: unknown) => {
        last = { request, error: String(cause) };
        console.error("polaris: open in editor failed", cause);
      });
    });
  }, []);

  return null;
};

/**
 * A Task row's menu, from ⋯ or a right-click (DESIGN.md, Claims): Approve, Accept… a,
 * Send back… s, Open in Review, Focus; and "Message the lead about this".
 */
import type { MessageAuthority } from "@polaris/protocol";
import {
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
  IconButton,
  DotsIcon,
} from "@polaris/ui";
import type { ReactNode } from "react";
import type { TaskRow } from "../model/index.ts";

export interface MenuActions {
  readonly onReview: (row: TaskRow, mode: "accept" | "send-back") => void;
  /** Records the user's verdict; the Lead still merges and accepts (spec §7). */
  readonly onApprove: (row: TaskRow) => void;
  readonly onFocus: (row: TaskRow) => void;
  readonly onOpenInReview: (row: TaskRow) => void;
  readonly onMessageLead: (row: TaskRow, authority: MessageAuthority) => void;
}

type Entry =
  | {
      readonly kind: "item";
      readonly label: string;
      readonly key?: string;
      readonly run: () => void;
    }
  | { readonly kind: "separator" }
  | { readonly kind: "label"; readonly text: string }
  | { readonly kind: "sub"; readonly label: string; readonly items: ReadonlyArray<Entry> };

export const menuEntries = (row: TaskRow, on: MenuActions): ReadonlyArray<Entry> => {
  const id = row.task.id;
  const review = row.projection.state === "review";

  const focus: Entry = { kind: "item", label: `Focus ${id}`, key: "↵", run: () => on.onFocus(row) };

  const open: Entry = { kind: "item", label: "Open in Review", run: () => on.onOpenInReview(row) };

  const message: Entry = {
    kind: "sub",
    label: "Message the lead about this",
    items: [
      {
        kind: "item",
        label: "Ask for a recommendation",
        run: () => on.onMessageLead(row, "recommend_and_return"),
      },
      {
        kind: "item",
        label: "Let it decide",
        run: () => on.onMessageLead(row, "may_decide_and_continue"),
      },
    ],
  };

  if (!review) return [focus, open, { kind: "separator" }, message];

  const approve: Entry =
    row.attempt?.approvedByUserAt == null
      ? { kind: "item", label: "Approve", run: () => on.onApprove(row) }
      : { kind: "label", text: "You approved · the lead merges" };

  return [
    approve,
    { kind: "item", label: "Accept…", key: "a", run: () => on.onReview(row, "accept") },
    { kind: "item", label: "Send back…", key: "s", run: () => on.onReview(row, "send-back") },
    ...(row.attempt?.approvedByUserAt == null
      ? [{ kind: "item", label: "Approve", run: () => on.onApprove(row) } satisfies Entry]
      : []),
    { kind: "separator" },
    open,
    focus,
    message,
    ...(row.promoted
      ? []
      : [{ kind: "label", text: "The lead is reviewing this claim" } satisfies Entry]),
  ];
};

const Dropdown = ({ entries }: { readonly entries: ReadonlyArray<Entry> }): ReactNode =>
  entries.map((e, n) => {
    switch (e.kind) {
      case "item":
        return (
          <DropdownMenuItem key={n} onSelect={e.run}>
            {e.label}
            {e.key === undefined ? null : <DropdownMenuShortcut>{e.key}</DropdownMenuShortcut>}
          </DropdownMenuItem>
        );
      case "separator":
        return <DropdownMenuSeparator key={n} />;
      case "label":
        return <DropdownMenuLabel key={n}>{e.text}</DropdownMenuLabel>;
      case "sub":
        return (
          <DropdownMenuSub key={n}>
            <DropdownMenuSubTrigger>{e.label}</DropdownMenuSubTrigger>
            <DropdownMenuSubContent>
              <Dropdown entries={e.items} />
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        );
    }
  });

const Context = ({ entries }: { readonly entries: ReadonlyArray<Entry> }): ReactNode =>
  entries.map((e, n) => {
    switch (e.kind) {
      case "item":
        return (
          <ContextMenuItem key={n} onSelect={e.run}>
            {e.label}
            {e.key === undefined ? null : <ContextMenuShortcut>{e.key}</ContextMenuShortcut>}
          </ContextMenuItem>
        );
      case "separator":
        return <ContextMenuSeparator key={n} />;
      case "label":
        return <ContextMenuLabel key={n}>{e.text}</ContextMenuLabel>;
      case "sub":
        return (
          <ContextMenuSub key={n}>
            <ContextMenuSubTrigger>{e.label}</ContextMenuSubTrigger>
            <ContextMenuSubContent>
              <Context entries={e.items} />
            </ContextMenuSubContent>
          </ContextMenuSub>
        );
    }
  });

/** The ⋯ button and its menu; `open` lets the a/s keys and previews drive it. */
export const RowMenu = ({
  row,
  on,
  open,
  onOpenChange,
}: {
  readonly row: TaskRow;
  readonly on: MenuActions;
  readonly open: boolean;
  readonly onOpenChange: (open: boolean) => void;
}) => (
  <DropdownMenu open={open} onOpenChange={onOpenChange}>
    <DropdownMenuTrigger asChild>
      <IconButton
        size="sm"
        label={`${row.task.id} actions`}
        icon={<DotsIcon size={14} />}
        className="opacity-0 group-hover/row:opacity-100 group-data-[selected]/row:opacity-100 data-[state=open]:opacity-100"
      />
    </DropdownMenuTrigger>
    <DropdownMenuContent align="end" className="min-w-56">
      <Dropdown entries={menuEntries(row, on)} />
    </DropdownMenuContent>
  </DropdownMenu>
);

export const RowContextMenu = ({
  row,
  on,
}: {
  readonly row: TaskRow;
  readonly on: MenuActions;
}) => (
  <ContextMenuContent className="min-w-56">
    <Context entries={menuEntries(row, on)} />
  </ContextMenuContent>
);

