/**
 * Runs an effect/rpc client for `DaemonRpcs` over one framed Wire.
 *
 * The `RpcClient.Protocol` mirrors effect/rpc's socket client protocol
 * (`makeProtocolSocket` in effect@4.0.0-rc.118 `RpcClient.ts`): requests are
 * routed back to the RpcClient that sent them, a lost connection fails every
 * in-flight request with an RpcClientError, and a ping loop detects a dead
 * peer. Unlike it, there is no built-in retry: a Wire is one connection, and
 * HostConnection owns reconnecting.
 */
import {
  type BlobError,
  type BlobId,
  type BlobSource,
  DaemonRpcs,
  makeWire,
  type Wire,
  type WireOptions,
} from "@polaris/protocol"
import { Deferred, Effect, type Scope } from "effect"
import { RpcClient, type RpcGroup, RpcSerialization } from "effect/rpc"
import { RpcClientDefect, RpcClientError } from "effect/rpc/RpcClientError"
import { constPing, type FromServerEncoded } from "effect/rpc/RpcMessage"
import type { ClientTransport } from "./transport.ts"

export type DaemonClient = RpcClient.RpcClient<RpcGroup.Rpcs<typeof DaemonRpcs>, RpcClientError>

export interface ClientBlobs {
  /** Send bytes to the Daemon; pass the returned id in the RPC that consumes them. */
  readonly offer: <E>(source: BlobSource<E>) => Effect.Effect<BlobId>
  /** Receive a blob the Daemon referenced in a response (e.g. `files.read`, `git.diff`). */
  readonly take: (blobId: BlobId) => Effect.Effect<Uint8Array, BlobError>
}

export interface RpcConnection {
  readonly client: DaemonClient
  readonly blobs: ClientBlobs
  readonly wire: Wire
  /** Fails when the connection is gone: closed, broken, or the peer stopped answering pings. */
  readonly lost: Effect.Effect<never, RpcClientError>
}

export interface RpcConnectionOptions {
  readonly wire?: WireOptions
  /** Ping interval; the connection is declared dead after 3 intervals with no traffic. */
  readonly pingIntervalMs?: number
}

const lostError = (message: string, cause?: unknown) =>
  new RpcClientError({ reason: new RpcClientDefect({ message, cause }) })

export const connectRpc = Effect.fnUntraced(function* (
  transport: ClientTransport,
  options: RpcConnectionOptions = {},
): Effect.fn.Return<RpcConnection, never, Scope.Scope> {
  const serialization = RpcSerialization.json
  const parser = serialization.makeUnsafe()
  const lost = yield* Deferred.make<never, RpcClientError>()
  const pingInterval = options.pingIntervalMs ?? 15_000
  let lastHeard = Date.now()
  let wire!: Wire

  const protocol = yield* RpcClient.Protocol.make(
    Effect.fnUntraced(function* (writeResponse, clientIds) {
      const requestClient = new Map<string | number, number>()
      let currentError: RpcClientError | undefined

      const broadcast = (response: FromServerEncoded) =>
        Effect.forEach(clientIds, (clientId) => writeResponse(clientId, response), {
          discard: true,
        })

      const onJson = (text: string) =>
        Effect.suspend(() => {
          lastHeard = Date.now()
          let responses: ReadonlyArray<FromServerEncoded>
          try {
            responses = parser.decode(text) as ReadonlyArray<FromServerEncoded>
          } catch (cause) {
            return broadcast({
              _tag: "ClientProtocolError",
              error: lostError("error decoding a message from the Daemon", cause),
            })
          }
          return Effect.forEach(
            responses,
            (response) => {
              if (response._tag === "Pong") return Effect.void
              if ("requestId" in response) {
                const clientId = requestClient.get(response.requestId)
                if (clientId !== undefined) {
                  if (response._tag === "Exit") requestClient.delete(response.requestId)
                  return writeResponse(clientId, response)
                }
              }
              return broadcast(response)
            },
            { discard: true },
          )
        })

      wire = yield* makeWire(transport, onJson, { ...options.wire, blobIdPrefix: "c" })

      const fail = (error: RpcClientError) =>
        Effect.suspend(() => {
          if (currentError !== undefined) return Effect.void
          currentError = error
          // Fail in-flight requests first: completing `lost` lets the owner close
          // this scope, which would interrupt us before the broadcast.
          return Effect.andThen(
            Deferred.fail(lost, error),
            broadcast({ _tag: "ClientProtocolError", error }),
            Deferred.fail(lost, error),
          ).pipe(Effect.uninterruptible)
        })

      yield* wire.closed.pipe(
        Effect.exit,
        Effect.flatMap((exit) =>
          fail(
            exit._tag === "Success"
              ? lostError("the Daemon closed the connection")
              : lostError(exit.cause.toString()),
          ),
        ),
        Effect.forkScoped,
      )

      // Keepalive: any traffic counts as liveness; pings keep a quiet link busy.
      yield* Effect.gen(function* () {
        while (true) {
          yield* Effect.sleep(pingInterval)
          if (Date.now() - lastHeard > pingInterval * 3) {
            yield* fail(lostError("the Daemon stopped answering"))
            return
          }
          yield* Effect.ignore(wire.sendJson(parser.encode(constPing) as string))
        }
      }).pipe(Effect.forkScoped)

      return {
        send: (clientId, request) =>
          Effect.suspend(() => {
            if (currentError !== undefined) return Effect.fail(currentError)
            if (request._tag === "Request") requestClient.set(request.id, clientId)
            const encoded = parser.encode(request)
            if (encoded === undefined) return Effect.void
            return wire
              .sendJson(encoded as string)
              .pipe(Effect.mapError((error) => lostError(error.message, error)))
          }),
        supportsAck: true,
        supportsTransferables: false,
        codecFor: serialization.codecFor,
      }
    }),
  )

  const client = yield* RpcClient.make(DaemonRpcs, { spanPrefix: "polaris.rpc" }).pipe(
    Effect.provideService(RpcClient.Protocol, protocol),
  )

  return {
    client,
    wire,
    blobs: { offer: wire.offerBlob, take: (blobId) => wire.takeBlob(blobId) },
    lost: Deferred.await(lost),
  }
})

/**
 * Every Harness on a Host, with what it needs (DESIGN.md, Settings S1): version,
 * status in neutral words, the setup line, and at most one action (sign in in
 * its own terminal, or its setup guide). Polaris never installs a Harness.
 * Opened from the pickers' "Other harnesses" link until Settings hosts it.
 */
import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  HarnessMark,
} from "@polaris/ui";
import { useState } from "react";
import { useApp } from "../../../shell/hooks.ts";
import { useAvailability } from "../live.ts";
import { type HarnessOption, otherCount, reasonLine, STATUS_LABELS } from "../model/options.ts";
import { SignInTerminal, type SignInTarget } from "./SignInTerminal.tsx";

/** Starts a Harness's sign-in hand-off on a Host; render `dialog` once. */
export const useSignIn = (hostKey: string) => {
  const host = useApp((s) => s.hosts.find((h) => h.key === hostKey));
  const [target, setTarget] = useState<SignInTarget | null>(null);

  const begin = (option: HarnessOption) => {
    if (option.signInArgv === null) return;
    setTarget({
      hostKey,
      hostLabel: host?.label ?? hostKey,
      harnessName: option.name,
      argv: option.signInArgv,
    });
  };

  return { begin, dialog: <SignInTerminal target={target} onClose={() => setTarget(null)} /> };
};

export const DocsLink = ({ option }: { readonly option: HarnessOption }) =>
  option.docsUrl === null ? null : (
    <a
      href={option.docsUrl}
      target="_blank"
      rel="noreferrer"
      className="text-label text-text-strong decoration-text-faint shrink-0 underline underline-offset-4"
    >
      Setup guide
    </a>
  );

/** One Harness's action: sign in when that's all it needs, else its setup guide; none when ready. */
export const HarnessAction = ({
  option,
  onSignIn,
}: {
  readonly option: HarnessOption;
  readonly onSignIn: (option: HarnessOption) => void;
}) => {
  if (option.status === "ready") return null;

  if (option.signInArgv !== null)
    return (
      <Button size="sm" onClick={() => onSignIn(option)} data-testid={`sign-in-${option.kind}`}>
        Sign in in terminal
      </Button>
    );

  return <DocsLink option={option} />;
};

const Row = ({
  option,
  onSignIn,
}: {
  readonly option: HarnessOption;
  readonly onSignIn: (option: HarnessOption) => void;
}) => (
  <li
    className="border-hairline flex flex-col gap-1 border-t px-4 py-3 first:border-t-0"
    data-testid={`availability-${option.kind}`}
    data-status={option.status}
  >
    <div className="flex items-center gap-3">
      <HarnessMark harness={option.kind} size={28} />
      <span className="text-label text-text-strong min-w-0 flex-1 truncate">{option.name}</span>
      <span className="text-code-inline text-text-subtle w-24 shrink-0 truncate font-mono">
        {option.version ?? ""}
      </span>
      <span className="text-caption text-text-subtle flex w-36 shrink-0 flex-col">
        <span>
          {option.signInKind === null
            ? STATUS_LABELS[option.status]
            : `${STATUS_LABELS[option.status]} · ${option.signInKind}`}
        </span>
        {option.note === null ? null : (
          <span data-testid={`note-${option.kind}`}>{option.note}</span>
        )}
      </span>
      <span className="flex w-36 shrink-0 justify-end">
        <HarnessAction option={option} onSignIn={onSignIn} />
      </span>
    </div>
    {option.setupLine === null && option.detail === null ? null : (
      <p className="text-caption text-text-subtle pl-10">
        {[option.setupLine, option.detail].filter((t) => t !== null).join(" ")}
      </p>
    )}
  </li>
);

export const AvailabilityList = ({ hostKey }: { readonly hostKey: string }) => {
  const { options, loading, refresh } = useAvailability(hostKey);
  const signIn = useSignIn(hostKey);

  return (
    <div className="flex flex-col gap-3">
      {loading ? <p className="text-caption text-text-subtle">Checking harnesses…</p> : null}
      <ul className="rounded-card border-hairline flex flex-col border">
        {options.map((option) => (
          <Row key={option.kind} option={option} onSignIn={signIn.begin} />
        ))}
      </ul>
      <div className="flex items-center gap-2">
        <p className="text-caption text-text-faint flex-1">
          Polaris drives the harnesses you already have; it never installs one.
        </p>
        <Button variant="ghost" size="sm" onClick={refresh} data-testid="availability-refresh">
          Check again
        </Button>
      </div>
      {signIn.dialog}
    </div>
  );
};

/** The Host's availability in a sheet: what the pickers' "Other harnesses" opens. */
export const AvailabilitySheet = ({
  hostKey,
  open,
  onOpenChange,
}: {
  readonly hostKey: string;
  readonly open: boolean;
  readonly onOpenChange: (open: boolean) => void;
}) => {
  const host = useApp((s) => s.hosts.find((h) => h.key === hostKey));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-[680px]" data-testid="availability-sheet">
        <DialogHeader>
          <DialogTitle>Harnesses on {host?.label ?? hostKey}</DialogTitle>
          <DialogDescription>
            What each harness needs before a session can run on it here.
          </DialogDescription>
        </DialogHeader>
        <div className="px-5 pb-5">
          <AvailabilityList hostKey={hostKey} />
        </div>
      </DialogContent>
    </Dialog>
  );
};

/** "Other harnesses (3)": the ones the pickers leave out, in the availability sheet. */
export const OtherHarnessesLink = ({
  hostKey,
  options,
}: {
  readonly hostKey: string;
  readonly options: ReadonlyArray<HarnessOption>;
}) => {
  const [open, setOpen] = useState(false);
  const others = otherCount(options);

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="text-caption text-text-default decoration-text-faint cursor-default self-start underline underline-offset-4"
        data-testid="other-harnesses"
      >
        {others === 0 ? "Harnesses on this host" : `Other harnesses (${others})`}
      </button>
      <AvailabilitySheet hostKey={hostKey} open={open} onOpenChange={setOpen} />
    </>
  );
};

/** Under a chosen Harness that can't start yet: its setup line, and sign-in or its docs. */
export const SetupNote = ({
  option,
  onSignIn,
}: {
  readonly option: HarnessOption;
  readonly onSignIn: (option: HarnessOption) => void;
}) => (
  <div
    className="rounded-card border-hairline bg-surface-raised flex items-center gap-3 border px-4 py-3"
    data-testid="harness-setup"
  >
    <div className="flex min-w-0 flex-1 flex-col gap-1">
      <p className="text-body text-text-default">
        {option.setupLine ?? `${option.name} can't start yet.`}
      </p>
      {option.detail === null ? null : (
        <p className="text-caption text-text-subtle">{option.detail}</p>
      )}
    </div>
    <HarnessAction option={option} onSignIn={onSignIn} />
  </div>
);

/**
 * When no Harness on the Host is ready: each one's reason in a line, its setup guide, and
 * sign-in where that's all it needs. Never an install or update action; Start stays off.
 */
export const NotReadyPanel = ({
  hostKey,
  options,
  onSignIn,
}: {
  readonly hostKey: string;
  readonly options: ReadonlyArray<HarnessOption>;
  readonly onSignIn: (option: HarnessOption) => void;
}) => {
  const host = useApp((s) => s.hosts.find((h) => h.key === hostKey));
  const { refresh } = useAvailability(hostKey);

  return (
    <div
      className="rounded-card border-hairline bg-surface-raised flex flex-col border"
      data-testid="harness-not-ready"
    >
      <div className="flex flex-col gap-0.5 px-4 pt-3 pb-2">
        <p className="text-label text-text-strong">
          No harness is ready on {host?.label ?? hostKey}
        </p>
        <p className="text-caption text-text-subtle">
          Polaris drives the harnesses you already have. Set one up, then check again.
        </p>
      </div>
      <ul className="flex flex-col">
        {options.map((option) => (
          <li
            key={option.kind}
            className="border-hairline flex items-center gap-3 border-t px-4 py-2"
            data-testid={`not-ready-${option.kind}`}
          >
            <HarnessMark harness={option.kind} size={20} />
            <span className="text-body text-text-default min-w-0 flex-1 truncate">
              {reasonLine(option)}
            </span>
            {option.signInArgv === null ? (
              <DocsLink option={option} />
            ) : (
              <HarnessAction option={option} onSignIn={onSignIn} />
            )}
          </li>
        ))}
      </ul>
      <div className="border-hairline flex justify-end border-t px-2 py-1.5">
        <Button variant="ghost" size="sm" onClick={refresh} data-testid="availability-refresh">
          Check again
        </Button>
      </div>
    </div>
  );
};

/**
 * "Ask the reviewer" at the foot of the risk column (Paper R1 1YD-0): a question about the
 * whole change, or the finding "Ask about this" picked. It continues the Reviewer's own
 * read-only session; the answer shows here, and findings it changes reach the summary.
 */
import type { SessionId, TurnId } from "@polaris/protocol";
import {
  ArrowUpIcon,
  Button,
  CloseIcon,
  Dither,
  PixelPolarisIcon,
  SeverityGlyph,
} from "@polaris/ui";
import { Predicate } from "effect";
import { useState } from "react";
import { useSession } from "../../session/hooks.ts";
import { type Ask, askReviewer, useAsks } from "../data/actions.ts";
import { setAskAbout, useAskAbout } from "../data/ui.ts";
import { answerOf, type TurnSnapshot } from "../model/answer.ts";
import type { Summary } from "../model/summary.ts";

const isMessage = Predicate.isTagged("AssistantMessage");

const useTurn = (hostKey: string, sessionId: SessionId, turnId: TurnId): TurnSnapshot | null => {
  const model = useSession(hostKey, sessionId);
  const view = model.turns.find((t) => t.turn.id === turnId);

  if (view === undefined) return null;
  const messages: Array<string> = [];

  for (const item of view.items) if (isMessage(item)) messages.push(item.text);

  for (const live of view.live.values()) {
    if (live.item !== null && isMessage(live.item)) messages.push(live.text);
  }

  return { status: view.turn.status, messages };
};

const Answer = ({
  hostKey,
  sessionId,
  turnId,
}: {
  readonly hostKey: string;
  readonly sessionId: SessionId;
  readonly turnId: TurnId;
}) => {
  const answer = answerOf(useTurn(hostKey, sessionId, turnId));

  if (answer.kind === "thinking") {
    return (
      <span className="text-caption text-text-subtle gap-gap flex items-center">
        <Dither hue="starlight" size={12} moving />
        The reviewer is looking…
      </span>
    );
  }

  return (
    <p
      className={
        answer.kind === "failed"
          ? "text-caption text-failed-text"
          : "text-caption text-text-default whitespace-pre-wrap"
      }
    >
      {answer.text}
    </p>
  );
};

const AskItem = ({
  hostKey,
  ask,
  summary,
}: {
  readonly hostKey: string;
  readonly ask: Ask;
  readonly summary: Summary;
}) => {
  const about = summary.findings.find((f) => f.id === ask.findingId);

  return (
    <div className="flex flex-col gap-1" data-testid="reviewer-ask">
      <p className="text-caption text-text-subtle">
        {about !== undefined && <span className="text-text-subtle">On “{about.title}”: </span>}
        {ask.question}
      </p>
      {ask.state.kind === "sending" && (
        <span className="text-caption text-text-faint">Asking…</span>
      )}
      {ask.state.kind === "failed" && (
        <p className="text-caption text-failed-text">{ask.state.message}</p>
      )}
      {ask.state.kind === "sent" && (
        <Answer hostKey={hostKey} sessionId={ask.state.sessionId} turnId={ask.state.turnId} />
      )}
    </div>
  );
};

const placeholderOf = (canAsk: boolean, aboutFinding: boolean) => {
  if (!canAsk) return "No reviewer ran: rules only";

  return aboutFinding ? "Ask about this finding" : "Ask the reviewer about this change";
};

export interface AskReviewerProps {
  readonly subjectKey: string;
  readonly hostKey: string;
  readonly summary: Summary;
}

export const AskReviewer = ({ subjectKey, hostKey, summary }: AskReviewerProps) => {
  const asks = useAsks(summary.id);
  const aboutId = useAskAbout(subjectKey);
  const about = summary.findings.find((f) => f.id === aboutId) ?? null;
  const [question, setQuestion] = useState("");
  const canAsk = summary.reviewer !== null && summary.reviewer.sessionId !== null;

  const ask = () => {
    if (question.trim() === "" || !canAsk) return;
    void askReviewer(hostKey, summary.id, about?.id ?? null, question);
    setQuestion("");
    setAskAbout(subjectKey, null);
  };

  return (
    <div className="flex flex-col gap-2 px-3 pt-2 pb-3" data-testid="ask-reviewer">
      {asks.slice(-2).map((a) => (
        <AskItem key={a.id} hostKey={hostKey} ask={a} summary={summary} />
      ))}
      {about !== null && (
        <div className="gap-gap text-caption text-text-subtle flex items-center">
          <SeverityGlyph severity={about.severity} tone="text" />
          <span className="min-w-0 flex-1 truncate">About “{about.title}”</span>
          <Button
            size="icon-sm"
            variant="ghost"
            aria-label="Ask about the whole change"
            onClick={() => setAskAbout(subjectKey, null)}
          >
            <CloseIcon size={12} />
          </Button>
        </div>
      )}
      <div className="rounded-card bg-surface-raised border-hairline pl-row-x gap-gap flex h-10 items-center border pr-1.5">
        <PixelPolarisIcon size={16} className="text-starlight shrink-0" />
        <input
          aria-label="Ask the reviewer"
          data-testid="ask-input"
          disabled={!canAsk}
          className="text-body text-text-default placeholder:text-text-faint min-w-0 flex-1 bg-transparent outline-none"
          placeholder={placeholderOf(canAsk, about !== null)}
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") ask();
          }}
        />
        <Button
          size="icon-sm"
          variant="secondary"
          className="rounded-full"
          aria-label="Ask"
          disabled={!canAsk || question.trim() === ""}
          onClick={ask}
        >
          <ArrowUpIcon size={12} />
        </Button>
      </div>
    </div>
  );
};

/**
 * blobs: bulk bytes through the blob channel. A large `files.read` (Daemon →
 * Client) and an `attachments.stage` upload (Client → Daemon), with the
 * Daemon's peak memory while each is in flight.
 */
import { join } from "node:path"
import { Effect } from "effect"
import { awaitReady, cleanup, connect, makeTempDir } from "../daemon.ts"
import { registerWorkspace, settle } from "../drive.ts"
import { randomFile } from "../fixtures.ts"
import { memory, type Scenario, throughput } from "../types.ts"

export const blobs: Scenario = {
  name: "blobs",
  description: "files.read download and attachment upload throughput, peak RSS",
  run: (ctx) =>
    Effect.gen(function* () {
      const size = (ctx.quick ? 16 : 100) * 1024 * 1024
      const dir = yield* Effect.acquireRelease(
        Effect.sync(() => makeTempDir("blobs")),
        (d) => Effect.sync(() => cleanup(d)),
      )
      const file = join(dir, "big.bin")
      yield* Effect.promise(() => Promise.resolve(randomFile(file, size)))
      const daemon = yield* ctx.launch()
      yield* awaitReady(daemon)
      const sampler = yield* ctx.sample(daemon, 50)
      const client = yield* connect(daemon, ctx.transport, "blobs")
      const workspaceId = yield* registerWorkspace(client, dir, "blobs")
      yield* settle(1000)
      const base = sampler.sample()

      // Download.
      const readFrom = base.t
      const t0 = performance.now()
      const read = yield* client.connection.client["files.read"]({
        path: file,
        offset: null,
        length: null,
      })
      if (read.content._tag !== "Blob") return yield* Effect.die(new Error("expected a blob"))
      const bytes = yield* client.connection.blobs.take(read.content.blobId)
      const readSeconds = (performance.now() - t0) / 1000
      if (bytes.byteLength !== size) {
        return yield* Effect.die(new Error(`read ${bytes.byteLength} of ${size} bytes`))
      }
      const readReport = sampler.report(readFrom - 1, sampler.sample().t)
      yield* settle(2000)

      // Upload.
      const uploadFrom = sampler.sample().t
      const t1 = performance.now()
      const blobId = yield* client.connection.blobs.offer(bytes)
      const staged = yield* client.connection.client["attachments.stage"]({
        sessionId: null,
        workspaceId,
        name: "big.bin",
        mimeType: "application/octet-stream",
        blobId,
      })
      const uploadSeconds = (performance.now() - t1) / 1000
      if (staged.size !== size) return yield* Effect.die(new Error(`staged ${staged.size} bytes`))
      const uploadReport = sampler.report(uploadFrom - 1, sampler.sample().t)
      yield* settle(2000)
      const after = sampler.sample()
      // After the measurements: the snapshot allocates.
      yield* ctx.peak(daemon, "after-upload")

      const mb = size / 1e6
      // Transfers allocate in proportion to the payload and GC timing moves the
      // peaks a lot: hold them to 35% or a quarter of the payload.
      const tolerance = { relative: 0.35, absolute: size / 1024 / 1024 / 4 }
      const blobMemory = (bytes: number) => memory(bytes, { tolerance })
      const rate = (mbPerS: number) =>
        throughput(mbPerS, "MB/s", { tolerance: { relative: 0.5, absolute: 0 } })
      return {
        metrics: {
          read_mb_per_s: rate(mb / readSeconds),
          read_rss_peak_over_base_mib: blobMemory(readReport.rssBytes.max - base.rssBytes),
          upload_mb_per_s: rate(mb / uploadSeconds),
          upload_rss_peak_over_base_mib: blobMemory(uploadReport.rssBytes.max - base.rssBytes),
          rss_after_mib: blobMemory(after.rssBytes),
          ...(base.footprintBytes !== null &&
          after.footprintBytes !== null &&
          uploadReport.footprintBytes
            ? {
                upload_footprint_peak_over_base_mib: memory(
                  uploadReport.footprintBytes.max - base.footprintBytes,
                ),
                footprint_retained_mib: blobMemory(after.footprintBytes - base.footprintBytes),
              }
            : {}),
          rss_retained_mib: blobMemory(after.rssBytes - base.rssBytes),
        },
        notes: [
          `${size / 1024 / 1024} MiB of incompressible bytes each way over ${ctx.transport}; RSS sampled every 50 ms`,
        ],
      }
    }),
}

