/**
 * `polaris bridge`: what `ssh <host> polaris bridge` runs. Pipes stdin/stdout
 * to the local Daemon socket byte for byte, with backpressure both ways, and
 * exits when either side closes. Frames pass through untouched; the bridge
 * never parses them.
 *
 * If no Daemon is listening and the Host uses Polaris' fallback supervisor
 * (`~/.polaris/bin/polaris-supervise`: Linux without systemd --user), the
 * bridge starts the supervisor, waits up to 5 s for the socket and tries
 * once more; nothing else may have started it since a reboot. Otherwise it
 * prints a reason on stderr and exits with BRIDGE_EXIT_NO_DAEMON, which the
 * Client maps to Needs Attention.
 *
 * With agent forwarding on for the Host, ssh sets SSH_AUTH_SOCK for this
 * process; the bridge repoints `~/.polaris/agent.sock` at it, so the Daemon and
 * its Harnesses can use one stable path that survives reconnects.
 */
import { renameSync, statSync, symlinkSync, unlinkSync } from "node:fs";
import { connect, type Socket } from "node:net";
import { join } from "node:path";
import { BRIDGE_EXIT_NO_DAEMON } from "@polaris/protocol/bridge";
import { paths } from "../paths.ts";

/** The stable agent socket path on this Host (a symlink to the latest forwarded agent). */
export const agentSocketPath = (): string => join(paths().root, "agent.sock");

const linkForwardedAgent = () => {
  const forwarded = process.env.SSH_AUTH_SOCK;

  if (forwarded === undefined || forwarded === agentSocketPath()) return;

  try {
    if (!statSync(forwarded).isSocket()) return;
    const temp = `${agentSocketPath()}.${process.pid}`;

    try {
      unlinkSync(temp);
    } catch {}

    symlinkSync(forwarded, temp);
    renameSync(temp, agentSocketPath());
  } catch {
    // Best effort: agent forwarding is optional.
  }
};

interface Source {
  pause(): void;
  resume(): void;
}

interface Sink {
  write(chunk: Uint8Array, callback: () => void): boolean;
  once(event: "drain", listener: () => void): unknown;
}

/**
 * Forwards chunks into `sink`, pausing `source` while the sink is backed up.
 * Resumes on the write callbacks as well as `drain`, which Bun does not always
 * emit for sockets.
 */
const pipe = (source: Source, sink: Sink) => {
  let inflight = 0;
  let paused = false;

  const resume = () => {
    if (paused) {
      paused = false;
      source.resume();
    }
  };

  return (chunk: Uint8Array) => {
    inflight++;

    const ok = sink.write(chunk, () => {
      inflight--;

      if (inflight === 0) resume();
    });

    if (!ok && !paused) {
      paused = true;
      source.pause();
      sink.once("drain", resume);
    }
  };
};

/** How long the bridge waits for a Daemon the fallback supervisor just started. */
export const SUPERVISOR_START_WAIT_MS = 5000;

export interface BridgeOptions {
  readonly socketPath?: string;
  /**
   * The fallback supervisor script (`~/.polaris/bin/polaris-supervise`, Linux
   * without systemd --user). When no Daemon answers and this file exists, the
   * bridge starts it and tries once more. Null turns that off.
   */
  readonly supervisor?: string | null;
  /** How long to wait for the Daemon after starting the supervisor. */
  readonly waitMs?: number;
}

const spawnSupervisor = (script: string) => {
  // Without arguments the script detaches itself (setsid, else nohup) and returns at once.
  Bun.spawn([script], { stdin: "ignore", stdout: "ignore", stderr: "ignore" }).unref();
};

/** Resolves true once something accepts a connection on `socketPath`. */
const probeSocket = (socketPath: string): Promise<boolean> =>
  new Promise((resolve) => {
    const socket = connect(socketPath);
    socket.once("connect", () => {
      socket.destroy();
      resolve(true);
    });
    socket.once("error", () => {
      socket.destroy();
      resolve(false);
    });
  });

const isFile = (path: string) => {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
};

/**
 * On a Host that relies on the fallback supervisor (nothing may have started
 * it since a reboot), start it and wait up to `waitMs` for the Daemon's
 * socket. False when there is no supervisor or the Daemon did not come up.
 */
const startDaemonViaSupervisor = async (
  socketPath: string,
  options: BridgeOptions
): Promise<boolean> => {
  const script =
    options.supervisor === undefined ? join(paths().bin, "polaris-supervise") : options.supervisor;

  if (script === null || !isFile(script)) return false;

  try {
    spawnSupervisor(script);
  } catch {
    return false;
  }

  const deadline = Date.now() + (options.waitMs ?? SUPERVISOR_START_WAIT_MS);

  for (;;) {
    if (await probeSocket(socketPath)) return true;

    if (Date.now() >= deadline) return false;
    await Bun.sleep(100);
  }
};

export const runBridge = (options: BridgeOptions = {}): Promise<number> =>
  new Promise((resolve) => {
    const socketPath = options.socketPath ?? paths().socket;
    linkForwardedAgent();
    const stdin = process.stdin;
    const stdout = process.stdout;
    let settled = false;
    let retried = false;
    // Bytes the Client sent before the socket connected (across a retry, too).
    let early: Array<Uint8Array> | null = [];
    let stdinEnded = false;
    let socket: Socket | null = null;
    let toSocket: ((chunk: Uint8Array) => void) | null = null;

    const finish = (code: number) => {
      if (settled) return;
      settled = true;
      stdin.pause();
      stdin.removeAllListeners("data");
      // Let buffered output reach the Client before exiting.
      stdout.write(new Uint8Array(0), () => resolve(code));
    };

    stdin.on("data", (chunk: Uint8Array) => {
      if (toSocket === null) early?.push(chunk);
      else toSocket(chunk);
    });
    stdin.once("end", () => {
      stdinEnded = true;

      if (toSocket !== null) socket?.end();
    });

    const attempt = () => {
      const current = connect(socketPath);
      socket = current;
      let connected = false;

      current.once("connect", () => {
        connected = true;
        const forward = pipe(stdin, current);
        toSocket = forward;
        const buffered = early ?? [];
        early = null;

        for (const chunk of buffered) forward(chunk);

        if (stdinEnded) current.end();
      });

      current.on("data", pipe(current, stdout));

      let failed = false;
      current.on("error", (error: NodeJS.ErrnoException) => {
        if (failed) return;
        failed = true;

        if (connected) {
          process.stderr.write(
            `polaris bridge: connection to the Daemon failed: ${error.message}\n`
          );
          finish(1);

          return;
        }

        const noDaemon = () => {
          process.stderr.write(
            `polaris bridge: no Daemon is running on this Host (nothing listening on ${socketPath}: ${error.code ?? error.message})\n`
          );
          finish(BRIDGE_EXIT_NO_DAEMON);
        };

        if (retried) return noDaemon();
        retried = true;
        void startDaemonViaSupervisor(socketPath, options).then((up) =>
          up ? attempt() : noDaemon()
        );
      });

      current.once("close", () => {
        if (connected) finish(0);
      });
    };

    attempt();
  });

/**
 * The multi-file rename preview in the real app on an isolated profile (Paper L7, L7b):
 * node apps/desktop/scripts/renamePreviewSmoke.ts (build first). An exported symbol used in
 * 3 files: Cancel leaves them unchanged; Accept lands unsaved edits, keeping a file's own
 * unsaved edits; one ⌘Z undoes everywhere; a file changed on disk refuses with a clear line.
 */
import { strict as assert } from "node:assert";
import { mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { _electron as electron, type Page } from "playwright-core";
import { startDaemon } from "./lib/daemon.ts";
import { APP_DIR, REPO_ROOT, stockElectronBinary } from "./lib/electron.ts";

const profile = realpathSync(mkdtempSync(join(tmpdir(), "polaris-rename-preview-")));

const userData = join(profile, "user-data");

const project = join(profile, "retry-demo");

const evidence = join(REPO_ROOT, ".dagr/evidence/slice-4c");

mkdirSync(userData);

mkdirSync(join(project, "src"), { recursive: true });

mkdirSync(evidence, { recursive: true });

writeFileSync(join(userData, "settings.json"), JSON.stringify({ welcomeSeen: true }));

writeFileSync(
  join(project, "tsconfig.json"),
  JSON.stringify({
    compilerOptions: { strict: true, module: "esnext", target: "es2022" },
    include: ["src"],
  })
);

const files = {
  "delay.ts":
    "export const BASE_DELAY_MS = 500;\n\nexport const delayFor = (attempt: number) => BASE_DELAY_MS * attempt;\n",
  "retry.ts":
    'import { BASE_DELAY_MS } from "./delay";\n\nexport const first = BASE_DELAY_MS;\nexport const second = BASE_DELAY_MS * 2;\n',
  "backoff.ts":
    'import { BASE_DELAY_MS } from "./delay";\n\nexport const cap = BASE_DELAY_MS * 10;\n',
};

for (const [name, text] of Object.entries(files)) writeFileSync(join(project, "src", name), text);

let daemon: Awaited<ReturnType<typeof startDaemon>> | undefined;

let app: Awaited<ReturnType<typeof electron.launch>> | undefined;

const until = async (what: string, check: () => Promise<boolean>, ms = 60_000) => {
  for (const end = Date.now() + ms; Date.now() < end;) {
    if (await check()) return;
    await new Promise((resolve) => setTimeout(resolve, 200));
  }

  throw new Error(`Timed out waiting for ${what}`);
};

const code = (page: Page) => page.locator(".cm-content").first().textContent();

const open = async (page: Page, name: string) => {
  await page
    .getByTestId("tree-row")
    .filter({ has: page.getByText(name, { exact: true }) })
    .click();
  await page
    .locator('[data-testid="editor-tab"][aria-selected="true"]')
    .filter({ hasText: name })
    .waitFor();
  await page.locator(".cm-content").first().waitFor();
};

const appearance = async (page: Page, theme: string) => {
  await page.evaluate(
    `window.polaris.request("settings.setAppearance", { patch: { theme: "${theme}", density: "balanced" } })`
  );
  await page.locator(`html[data-theme="${theme}"]`).waitFor({ state: "attached" });
  await page.waitForTimeout(300);
};

/** F2 on BASE_DELAY_MS in delay.ts, renaming it to `to`, until the preview shows. */
const rename = async (page: Page, to: string) => {
  await open(page, "delay.ts");
  await page.locator(".cm-line").first().click();
  await page.keyboard.press("Home");

  for (let i = 0; i < 15; i++) await page.keyboard.press("ArrowRight");

  await until(
    "the rename preview",
    async () => {
      if ((await page.getByTestId("rename-preview").count()) > 0) return true;

      if ((await page.getByTestId("rename-field").count()) === 0) await page.keyboard.press("F2");
      await page.getByLabel("New name").fill(to);
      await page.keyboard.press("Enter");
      await page.waitForTimeout(1500);

      if ((await page.getByTestId("rename-field").count()) > 0) await page.keyboard.press("Escape");

      return (await page.getByTestId("rename-preview").count()) > 0;
    },
    120_000
  );
};

try {
  daemon = await startDaemon({ home: profile, benchHarness: true });
  app = await electron.launch({
    executablePath: stockElectronBinary(),
    args: [APP_DIR],
    env: {
      ...process.env,
      POLARIS_DESKTOP_LOCAL_SOCKET: daemon.socketPath,
      POLARIS_DESKTOP_BENCH_HARNESS: "1",
      POLARIS_DESKTOP_USER_DATA: userData,
      POLARIS_DESKTOP_HIDDEN: "1",
    },
  });

  const page = await app.firstWindow();
  await page.setViewportSize({ width: 1440, height: 900 });
  await page
    .locator('[data-host="local"][data-connection="connected"]')
    .waitFor({ timeout: 20_000 });
  await page.evaluate(
    `window.polaris.request("dispatch", { hostKey: "local", commandId: crypto.randomUUID(), command: { _tag: "RegisterWorkspace", path: ${JSON.stringify(project)}, name: "retry-demo" } })`
  );
  await appearance(page, "dark");
  await page.keyboard.press("Meta+3");
  await page
    .getByTestId("tree-row")
    .filter({ has: page.getByText("src", { exact: true }) })
    .click({ timeout: 20_000 });

  // retry.ts has its own unsaved edit before the rename.
  await open(page, "retry.ts");
  await page.locator(".cm-line").last().click();
  await page.keyboard.press("End");
  await page.keyboard.type("// mine");
  await open(page, "delay.ts");
  await page
    .locator('[data-testid="language-pill"]:is([data-kind="ready"], [data-kind="bundled"])')
    .waitFor({ timeout: 240_000 });

  // Cancel (esc) changes nothing.
  await rename(page, "RETRY_DELAY_MS");
  assert.equal(await page.getByTestId("rename-file").count(), 3);
  await page.keyboard.press("Escape");
  await page.getByTestId("rename-preview").waitFor({ state: "detached" });
  assert.ok((await code(page))?.includes("BASE_DELAY_MS"));
  console.log("Cancel: nothing renamed");

  // The preview in both themes.
  await rename(page, "RETRY_DELAY_MS");
  const preview = page.getByTestId("rename-preview");
  assert.ok((await preview.textContent())?.includes("Rename in 3 files"));
  assert.ok((await preview.textContent())?.includes("unsaved edits kept"));
  await page.screenshot({ path: join(evidence, "rename-preview-dark.png") });
  await appearance(page, "light");
  await preview.getByTestId("rename-file").nth(1).getByRole("button").first().click();
  await page.screenshot({ path: join(evidence, "rename-preview-light.png") });
  await appearance(page, "dark");

  // Accept (⌘↵): every file renamed as unsaved edits; retry.ts keeps its own edit.
  await page.keyboard.press("Meta+Enter");
  await preview.waitFor({ state: "detached", timeout: 30_000 });
  await until(
    "delay.ts renamed",
    async () => (await code(page))?.includes("RETRY_DELAY_MS") ?? false
  );
  await open(page, "retry.ts");
  const retry = (await code(page)) ?? "";
  assert.ok(retry.includes("RETRY_DELAY_MS") && !retry.includes("BASE_DELAY_MS"), retry);
  assert.ok(retry.includes("// mine"), "retry.ts keeps its unsaved edit");
  await open(page, "backoff.ts");
  assert.ok((await code(page))?.includes("RETRY_DELAY_MS"));
  assert.equal(await page.getByTestId("refactor-recovery").count(), 0, "no recovery strip");
  await page.screenshot({ path: join(evidence, "rename-accepted-dark.png") });
  console.log("Accept: 3 files renamed as unsaved edits; retry.ts kept its own edit");

  // One ⌘Z, in any file it touched, undoes it everywhere.
  await page.locator(".cm-content").first().click();
  await page.keyboard.press("Meta+z");
  await until(
    "backoff.ts restored",
    async () => (await code(page))?.includes("BASE_DELAY_MS") ?? false
  );
  await open(page, "delay.ts");
  assert.ok((await code(page))?.includes("BASE_DELAY_MS"));
  await open(page, "retry.ts");
  const restored = (await code(page)) ?? "";
  assert.ok(restored.includes("BASE_DELAY_MS") && restored.includes("// mine"), restored);
  console.log("⌘Z: undone in all 3 files; retry.ts still has its own edit");

  // A file changed on disk since the preview refuses with one clear line.
  await rename(page, "RETRY_DELAY_MS");
  writeFileSync(join(project, "src", "backoff.ts"), files["backoff.ts"] + "// changed elsewhere\n");
  await page.waitForTimeout(1500);
  await page.keyboard.press("Meta+Enter");
  const alert = page.getByTestId("rename-preview").getByRole("alert");
  await alert.waitFor({ timeout: 30_000 });
  console.log(`Stale: ${await alert.textContent()}`);
  await page.screenshot({ path: join(evidence, "rename-stale-dark.png") });
  await page.keyboard.press("Escape");
  await page.getByTestId("rename-preview").waitFor({ state: "detached" });
  assert.ok((await code(page))?.includes("BASE_DELAY_MS"), "nothing renamed after a refusal");
  await page.waitForTimeout(1000);
  await page.screenshot({ path: join(evidence, "rename-stale-after-dark.png") });
  console.log(
    `Recovery strip after refusal: ${await page.getByTestId("refactor-preview").count()}`
  );
  console.log("PASS");
} catch (error) {
  const page = app === undefined ? null : await app.firstWindow();
  await page?.screenshot({ path: join(evidence, "rename-failure.png") }).catch(() => undefined);
  throw error;
} finally {
  await app?.evaluate(({ app: electronApp }) => electronApp.exit()).catch(() => undefined);
  await daemon?.stop();
  rmSync(profile, { recursive: true, force: true });
}

/**
 * The preload script: exposes the typed `PolarisApi` as `window.polaris`
 * through `contextBridge`. Sandboxed, so it may require nothing but `electron`.
 * One IPC listener demultiplexes every subscription's batched items.
 */
import { contextBridge, ipcRenderer } from "electron";
import {
  type BatchEntry,
  CHANNELS,
  type AppEvent,
  type PolarisApi,
  type SubscriptionListener,
} from "../shared/api.ts";

const listeners = new Map<number, SubscriptionListener<unknown>>();

let nextId = 1;

ipcRenderer.on(CHANNELS.batch, (_event, entries: ReadonlyArray<BatchEntry>) => {
  for (const entry of entries) {
    const listener = listeners.get(entry.id);

    if (listener === undefined) continue;

    if (entry.items.length > 0) listener.items(entry.items);

    if (entry.end !== undefined) {
      listeners.delete(entry.id);
      listener.end?.(entry.end);
    }
  }
});

const api: PolarisApi = {
  request: (method, input) => ipcRenderer.invoke(CHANNELS.request, { method, input }),
  subscribe: (kind, input, listener) => {
    const id = nextId++;

    // SAFETY: the main process only sends items of `kind` under this id (see main/ipc/subscriptions.ts).
    listeners.set(id, listener as SubscriptionListener<unknown>);
    ipcRenderer.send(CHANNELS.subscribe, { id, kind, input });

    return () => {
      if (!listeners.delete(id)) return;
      ipcRenderer.send(CHANNELS.unsubscribe, { id });
    };
  },
  onAppEvent: (listener) => {
    const handler = (_event: Electron.IpcRendererEvent, event: AppEvent) => listener(event);

    ipcRenderer.on(CHANNELS.app, handler);

    return () => {
      ipcRenderer.off(CHANNELS.menu, handler);
    };
  },
};

contextBridge.exposeInMainWorld("polaris", api);

/**
 * The tabs over Review's centre pane (Paper R9 AMW-0): each label with its figure, the
 * chosen one on `fill-selected`, and the jump to Changes trailing. ⌘⇧[ / ⌘⇧] cycle them.
 */
import { cn, Kbd, Tooltip, TooltipContent, TooltipTrigger } from "@polaris/ui";
import { type TabId, TAB_LABELS } from "../model/tabs.ts";

export interface TabBarProps {
  readonly tabs: ReadonlyArray<TabId>;
  readonly current: TabId;
  readonly figures: Readonly<Partial<Record<TabId, string>>>;
  /** What a tab's tooltip says beyond its label ("9 files, 0 viewed"). */
  readonly hints: Readonly<Partial<Record<TabId, string>>>;
  /** A tab whose content changed since the last review ("updated", "3 new"). */
  readonly news: Readonly<Partial<Record<TabId, string>>>;
  readonly onPick: (tab: TabId) => void;
  /** "Review changes", "Review 2 new commits"; null hides the jump (on Changes). */
  readonly jumpLabel: string | null;
}

const NEXT = "⇧⌘]";

const PREVIOUS = "⇧⌘[";

const keyTo = (tabs: ReadonlyArray<TabId>, current: TabId, tab: TabId) => {
  const from = tabs.indexOf(current);
  const to = tabs.indexOf(tab);

  if ((from + 1) % tabs.length === to) return NEXT;

  return (to + 1) % tabs.length === from ? PREVIOUS : null;
};

export const TabBar = ({ tabs, current, figures, hints, news, onPick, jumpLabel }: TabBarProps) => (
  <div
    role="tablist"
    aria-label="Review"
    data-testid="review-tabs"
    className="border-hairline px-panel flex h-10 shrink-0 items-center gap-1 border-b"
  >
    {tabs.map((tab) => {
      const key = keyTo(tabs, current, tab);
      const hint = [TAB_LABELS[tab], hints[tab]].filter((p) => p !== undefined).join(" · ");

      return (
        <Tooltip key={tab}>
          <TooltipTrigger asChild>
            <button
              type="button"
              role="tab"
              id={`review-tab-${tab}`}
              aria-selected={tab === current}
              aria-controls={`review-panel-${tab}`}
              data-testid={`review-tab-${tab}`}
              onClick={() => onPick(tab)}
              className={cn(
                "rounded-control h-tree-row px-row-x flex shrink-0 cursor-default items-center gap-1.5",
                tab === current ? "bg-fill-selected" : "hover:bg-fill-hover"
              )}
            >
              <span
                className={cn(
                  "text-body font-medium",
                  tab === current ? "text-text-strong" : "text-text-subtle"
                )}
              >
                {TAB_LABELS[tab]}
              </span>
              {figures[tab] !== undefined && (
                <span className="text-caption text-text-subtle tabular">{figures[tab]}</span>
              )}
              {news[tab] !== undefined && (
                <span className="text-caption text-text-default">{news[tab]}</span>
              )}
            </button>
          </TooltipTrigger>
          <TooltipContent side="bottom" className="flex items-center gap-2">
            {hint}
            {key !== null && <Kbd>{key}</Kbd>}
          </TooltipContent>
        </Tooltip>
      );
    })}
    <span className="flex-1" />
    {jumpLabel !== null && (
      <button
        type="button"
        data-testid="review-jump-changes"
        onClick={() => onPick("changes")}
        className="rounded-control h-tree-row pr-row-pad bg-fill-selected text-body text-text-strong hover:bg-fill-selected/70 gap-gap flex shrink-0 cursor-default items-center pl-3 font-medium"
      >
        {jumpLabel} →{current === "overview" && <Kbd>{NEXT}</Kbd>}
      </button>
    )}
  </div>
);
